  for r in select * from public.groups where project_id = p_source order by position loop
    insert into public.groups (project_id, name, color, position)
    values (new_id, r.name, r.color, r.position) returning id into nid;
    group_map := group_map || jsonb_build_object(r.id::text, nid);
  end loop;

  -- Repeating tasks: copy only the latest one of each series.
  for r in select * from public.tasks t where t.project_id = p_source
             and not exists (select 1 from public.tasks x where x.repeated_from = t.id)
           order by position loop
    insert into public.tasks (project_id, group_id, title, description, status_id, priority,
                              start_date, due_date, progress, position, custom_values, repeat_rule, repeat_until, is_internal)
    values (new_id, (group_map->>r.group_id::text)::uuid, r.title, r.description,
            -- New copies start at the first ("not started") label, not the source's progress.
            (select s.id from public.status_labels s where s.project_id = new_id order by s.position limit 1),
            r.priority, r.start_date + shift, r.due_date + shift, 0, r.position, r.custom_values,
            r.repeat_rule, r.repeat_until + shift, r.is_internal)
    returning id into nid;
    task_map := task_map || jsonb_build_object(r.id::text, nid);

    insert into public.task_checklist_items (task_id, title, is_done, position)
    select nid, title, false, position from public.task_checklist_items where task_id = r.id;
  end loop;

  insert into public.task_dependencies (task_id, depends_on_task_id)
  select (task_map->>d.task_id::text)::uuid, (task_map->>d.depends_on_task_id::text)::uuid
  from public.task_dependencies d
  join public.tasks t on t.id = d.task_id
  where t.project_id = p_source and task_map ? d.task_id::text and task_map ? d.depends_on_task_id::text;

  insert into public.milestones (project_id, title, description, date, color)
  select new_id, title, description, date + shift, color from public.milestones where project_id = p_source;

  return new_id;
end;
$$;


-- >>>>>>>>>>>>>>>>>>>> 20261128000017_project_visibility.sql
-- =====================================================================
-- Orion Projects — 0017 People only see projects they're on
--
-- Before: managers saw and could change every project.
-- Now: managers, technicians and basic users only see projects they've been
-- added to (plus, for managers, projects they created and templates).
-- Administrators still see everything. Whoever creates a project is added to
-- its team automatically.
-- =====================================================================

-- Managers: projects they're on, projects they created, and templates.
create or replace function app.manager_has_project(p_project uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select app.is_project_member(p_project)
      or exists (select 1 from public.projects p where p.id = p_project and (p.is_template or p.created_by = auth.uid()))
$$;

create or replace function app.can_view_project(p_project uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select case app.current_role()
    when 'admin' then true
    when 'manager' then app.manager_has_project(p_project)
    when 'technician' then app.is_project_member(p_project)
    when 'basic' then app.is_project_member(p_project)
    else false
  end
$$;

create or replace function app.can_edit_project(p_project uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select case app.current_role()
    when 'admin' then true
    when 'manager' then app.manager_has_project(p_project)
    when 'technician' then app.is_project_member(p_project)
    else false
  end
$$;

-- Manager-level changes on a project (settings, people, planning, deleting, client links).
create or replace function app.can_manage_project(p_project uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select case app.current_role()
    when 'admin' then true
    when 'manager' then app.manager_has_project(p_project)
    else false
  end
$$;

-- Whoever creates a project is recorded and added to its team.
create or replace function app.project_set_creator()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.created_by := coalesce(new.created_by, auth.uid());
  return new;
end;
$$;
drop trigger if exists projects_set_creator on public.projects;
create trigger projects_set_creator before insert on public.projects
  for each row execute function app.project_set_creator();

create or replace function app.project_add_creator()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if new.created_by is not null and not new.is_template then
    insert into public.project_members (project_id, user_id, added_by)
    values (new.id, new.created_by, new.created_by)
    on conflict do nothing;
  end if;
  return null;
end;
$$;
drop trigger if exists projects_add_creator on public.projects;
create trigger projects_add_creator after insert on public.projects
  for each row execute function app.project_add_creator();

-- ---------------------------------------------------------------- policies
-- Read: also check "created by me" on the row itself, so a manager can see the project
-- they're creating in the same statement (before the helper functions can see it).
drop policy "projects: read if visible" on public.projects;
create policy "projects: read if visible" on public.projects
  for select to authenticated
  using (app.can_view_project(id) or (created_by = auth.uid() and app.is_manager_or_above()));

drop policy "projects: manager update" on public.projects;
create policy "projects: manager update" on public.projects
  for update to authenticated using (app.can_manage_project(id)) with check (app.can_manage_project(id));

drop policy "members: manager insert" on public.project_members;
drop policy "members: manager delete" on public.project_members;
create policy "members: manager insert" on public.project_members
  for insert to authenticated with check (app.can_manage_project(project_id));
create policy "members: manager delete" on public.project_members
  for delete to authenticated using (app.can_manage_project(project_id));

-- These were "for all" for every manager (which also allowed reading every project's settings).
drop policy "labels: manager write" on public.status_labels;
create policy "labels: manager write" on public.status_labels
  for all to authenticated using (app.can_manage_project(project_id)) with check (app.can_manage_project(project_id));
drop policy "columns: manager write" on public.project_columns;
create policy "columns: manager write" on public.project_columns
  for all to authenticated using (app.can_manage_project(project_id)) with check (app.can_manage_project(project_id));
drop policy "groups: manager write" on public.groups;
create policy "groups: manager write" on public.groups
  for all to authenticated using (app.can_manage_project(project_id)) with check (app.can_manage_project(project_id));
drop policy "milestones: manager write" on public.milestones;
create policy "milestones: manager write" on public.milestones
  for all to authenticated using (app.can_manage_project(project_id)) with check (app.can_manage_project(project_id));

drop policy "tasks: manager delete" on public.tasks;
create policy "tasks: manager delete" on public.tasks
  for delete to authenticated using (app.can_manage_project(project_id));

drop policy "assignees: manager insert" on public.task_assignees;
drop policy "assignees: manager delete" on public.task_assignees;
create policy "assignees: manager insert" on public.task_assignees
  for insert to authenticated with check (
    app.can_manage_project(app.task_project(task_id))
    or (user_id = auth.uid() and app.can_edit_project(app.task_project(task_id)))
  );
create policy "assignees: manager delete" on public.task_assignees
  for delete to authenticated using (
    app.can_manage_project(app.task_project(task_id))
    or (user_id = auth.uid() and app.can_edit_project(app.task_project(task_id)))
  );

drop policy "deps: manager write" on public.task_dependencies;
create policy "deps: manager write" on public.task_dependencies
  for all to authenticated
  using (app.can_manage_project(app.task_project(task_id)))
  with check (app.can_manage_project(app.task_project(task_id)));

drop policy "attachments: uploader or manager delete" on public.attachments;
create policy "attachments: uploader or manager delete" on public.attachments
  for delete to authenticated using (
    app.can_view_project(app.task_project(task_id))
    and (uploaded_by = auth.uid() or app.can_manage_project(app.task_project(task_id)))
  );

drop policy "share links: manager all" on public.share_links;
create policy "share links: manager all" on public.share_links
  for all to authenticated using (app.can_manage_project(project_id)) with check (app.can_manage_project(project_id));

drop policy "project files: uploader or manager delete" on storage.objects;
create policy "project files: uploader or manager delete" on storage.objects
  for delete to authenticated
  using (bucket_id = 'project-files'
         and app.can_view_project(app.try_uuid(app.path_folder(name, 1)))
         and (owner_id = auth.uid()::text or app.can_manage_project(app.try_uuid(app.path_folder(name, 1)))));

-- Chats: managers rename/archive a project's chat only if it's their project.
drop policy "channels: manager update" on public.channels;
create policy "channels: manager update" on public.channels
  for update to authenticated
  using (app.is_manager_or_above() and (project_id is null or app.can_manage_project(project_id)))
  with check (app.is_manager_or_above() and (project_id is null or app.can_manage_project(project_id)));

-- Daily updates: managers change updates only on their own projects.
create or replace function app.can_modify_daily_update(p_update uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.daily_updates d
    where d.id = p_update
      and (
        app.can_manage_project(d.project_id)
        or (d.author_id = auth.uid()
            and d.created_at > now() - interval '24 hours'
            and app.can_edit_project(d.project_id))
      )
  )
$$;

-- ---------------------------------------------------------------- functions
-- Team overview (who has posted today): only the manager's own projects.
create or replace function public.get_daily_status(p_date date)
returns jsonb
language plpgsql stable security invoker
set search_path = ''
as $$
begin
  if not app.is_manager_or_above() then
    return null;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'project', jsonb_build_object('id', p.id, 'name', p.name, 'color', p.color),
      'update_count', (select count(*) from public.daily_updates d where d.project_id = p.id and d.work_date = p_date),
      'people', coalesce((
        select jsonb_agg(jsonb_build_object(
          'user_id', pr.id, 'first_name', pr.first_name, 'last_name', pr.last_name, 'email', pr.email, 'avatar_url', pr.avatar_url,
          'posted', exists (select 1 from public.daily_updates d where d.project_id = p.id and d.author_id = pr.id and d.work_date = p_date)
        ) order by pr.first_name, pr.last_name)
        from public.project_members m
        join public.profiles pr on pr.id = m.user_id
        where m.project_id = p.id and pr.role = 'technician' and pr.status = 'active'
      ), '[]')
    ) order by p.name)
    from public.projects p
    where p.status = 'active' and not p.is_template and app.can_view_project(p.id)
  ), '[]');
end;
$$;

-- Daily Update form: only projects you're on (admins: any).
create or replace function public.get_postable_projects()
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'color', p.color) order by p.name), '[]')
  from public.projects p
  where p.status = 'active' and not p.is_template and app.can_edit_project(p.id)
    and (app.is_admin() or app.is_project_member(p.id))
$$;

-- @mention lists in project chats: the project's people (and administrators).
create or replace function public.get_channel_people(p_channel uuid)
returns jsonb
language plpgsql stable security invoker
set search_path = ''
as $$
declare c public.channels%rowtype;
begin
  select * into c from public.channels where id = p_channel;
  if not found then return null; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('user_id', pr.id, 'first_name', pr.first_name, 'last_name', pr.last_name, 'email', pr.email, 'avatar_url', pr.avatar_url)
                     order by pr.first_name, pr.last_name)
    from public.profiles pr
    where pr.status = 'active'
      and case c.type
            when 'general' then true
            when 'management' then pr.role in ('admin', 'manager')
            when 'project' then pr.role = 'admin'
                             or exists (select 1 from public.project_members m where m.project_id = c.project_id and m.user_id = pr.id)
          end
  ), '[]');
end;
$$;

-- Chat notifications follow the same rule.
create or replace function app.on_message_chat_push()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  c public.channels%rowtype;
  who text;
  preview text;
  att record;
begin
  select * into c from public.channels where id = new.channel_id;
  if not found or c.archived or new.deleted_at is not null then
    return null;
  end if;

  who := app.person_name(new.author_id);
  preview := left(regexp_replace(new.body, '\s+', ' ', 'g'), 180);
  if preview = '' then
    -- Photo or file only. (This trigger runs at the end of the transaction, so attachments exist.)
    select a.mime_type, a.file_name into att from public.message_attachments a where a.message_id = new.id order by a.created_at limit 1;
    preview := case when att.mime_type like 'image/%' then '📷 Photo' when att.file_name is not null then '📎 ' || att.file_name else 'Sent a file' end;
  end if;

  insert into public.push_outbox (user_id, title, body, link, tag, sender)
  select pr.id,
         c.name,
         preview,
         '/chats/' || c.id,
         'chat-' || c.id,
         case when new.parent_id is not null then who || ' (reply)' else who end
  from public.profiles pr
  where pr.status = 'active'
    and pr.id <> coalesce(new.author_id, '00000000-0000-0000-0000-000000000000'::uuid)
    and not (pr.id = any (coalesce(new.mentions, '{}')))
    and case c.type
          when 'general' then true
          when 'management' then pr.role in ('admin', 'manager')
          when 'project' then pr.role = 'admin'
                           or exists (select 1 from public.project_members m where m.project_id = c.project_id and m.user_id = pr.id)
        end
    and not exists (select 1 from public.channel_members cm where cm.channel_id = c.id and cm.user_id = pr.id and cm.muted)
    and not exists (
      select 1 from public.notification_preferences np
      where np.user_id = pr.id and (not np.push_enabled or (np.types ->> 'chat.message') = 'false')
    )
    and exists (select 1 from public.push_subscriptions s where s.user_id = pr.id);
  return null;
end;
$$;

grant execute on all functions in schema app to authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261129000018_copy_task.sql
-- =====================================================================
-- Orion Projects — 0018 Copy a task to other projects
--
-- e.g. an internal, repeating "Monthly bill" set up once and copied to other
-- projects with a different date. Copies: name, description, priority,
-- internal + repeat settings, checklist (unticked) and extra-column values
-- (matched by column name). Not copied: status, progress, comments, files,
-- history, "waiting for" links. Owners are kept only if they're on the target
-- project (and, for technicians, only themselves).
-- =====================================================================

create or replace function public.copy_task_to_projects(p_task uuid, p_targets jsonb)
returns jsonb
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  src public.tasks%rowtype;
  tgt record;
  shift integer;
  new_id uuid;
  first_status uuid;
  grp uuid;
  vals jsonb;
  result jsonb := '[]';
begin
  select * into src from public.tasks where id = p_task;
  if not found or not app.can_view_project(src.project_id) then
    raise exception 'Task not found';
  end if;
  if jsonb_typeof(p_targets) <> 'array' or jsonb_array_length(p_targets) = 0 or jsonb_array_length(p_targets) > 50 then
    raise exception 'Choose at least one project';
  end if;

  for tgt in
    select (x->>'project_id')::uuid as project_id, nullif(x->>'group_id', '')::uuid as group_id, nullif(x->>'due_date', '')::date as due_date
    from jsonb_array_elements(p_targets) x
  loop
    if not app.can_edit_project(tgt.project_id) then
      raise exception 'You can''t add tasks to one of the chosen projects' using errcode = '42501';
    end if;

    -- Group: the one chosen (must belong to that project), else same name, else the first.
    select g.id into grp from public.groups g where g.id = tgt.group_id and g.project_id = tgt.project_id;
    if grp is null then
      select g.id into grp from public.groups g
      where g.project_id = tgt.project_id
      order by (g.name = (select s.name from public.groups s where s.id = src.group_id)) desc, g.position, g.created_at
      limit 1;
    end if;
    if grp is null then
      if not app.can_manage_project(tgt.project_id) then
        raise exception 'One of the chosen projects has no groups yet — ask its manager to add one';
      end if;
      insert into public.groups (project_id, name, position) values (tgt.project_id, 'Tasks', 1) returning id into grp;
    end if;

    select s.id into first_status from public.status_labels s
    where s.project_id = tgt.project_id and not s.is_done order by s.position limit 1;

    -- Dates move together: the start keeps its distance from the due date.
    shift := case when tgt.due_date is not null and src.due_date is not null then tgt.due_date - src.due_date else 0 end;

    -- Extra columns: copy values into columns with the same name and type.
    select coalesce(jsonb_object_agg(tc.id::text, src.custom_values -> sc.id::text), '{}') into vals
    from public.project_columns sc
    join public.project_columns tc on tc.project_id = tgt.project_id and lower(tc.name) = lower(sc.name) and tc.kind = sc.kind
    where sc.project_id = src.project_id and src.custom_values ? sc.id::text and sc.kind <> 'file';

    insert into public.tasks (project_id, group_id, title, description, status_id, priority, start_date, due_date, position,
                              custom_values, internal_notes, created_by, repeat_rule, repeat_until, is_internal)
    values (tgt.project_id, grp, src.title, src.description, first_status, src.priority,
            case when src.due_date is null and tgt.due_date is not null then null else src.start_date + shift end,
            coalesce(tgt.due_date, src.due_date),
            coalesce((select max(t.position) from public.tasks t where t.group_id = grp), 0) + 1,
            vals, src.internal_notes, auth.uid(), src.repeat_rule, src.repeat_until + shift, src.is_internal)
    returning id into new_id;

    insert into public.task_checklist_items (task_id, title, is_done, position)
    select new_id, c.title, false, c.position from public.task_checklist_items c where c.task_id = src.id;

    -- Owners who are on the target project (technicians may only keep themselves).
    insert into public.task_assignees (task_id, user_id, assigned_by)
    select new_id, a.user_id, auth.uid()
    from public.task_assignees a
    join public.project_members m on m.project_id = tgt.project_id and m.user_id = a.user_id
    where a.task_id = src.id
      and (app.can_manage_project(tgt.project_id) or a.user_id = auth.uid());

    result := result || jsonb_build_object('project_id', tgt.project_id, 'task_id', new_id);
  end loop;
  return result;
end;
$$;
revoke all on function public.copy_task_to_projects(uuid, jsonb) from public, anon;
grant execute on function public.copy_task_to_projects(uuid, jsonb) to authenticated;


-- >>>>>>>>>>>>>>>>>>>> 20261130000019_chat_media.sql
-- =====================================================================
-- Orion Projects — 0019 Photos & files of a chat
--
-- Every photo or file shared in a chat, newest first (like WhatsApp's "Media
-- and docs"). Runs as the caller, so chat permissions apply: you only get
-- media from chats you can read. Deleted messages are left out.
-- =====================================================================

create or replace function public.get_channel_media(
  p_channel uuid,
  p_kind text default 'photos',      -- 'photos' or 'files'
  p_before timestamptz default null,
  p_limit integer default 60
)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(x order by x->>'created_at' desc, x->>'id' desc), '[]')
  from (
    select jsonb_build_object(
      'id', a.id, 'message_id', m.id, 'parent_id', m.parent_id,
      'storage_path', a.storage_path, 'file_name', a.file_name, 'mime_type', a.mime_type,
      'size_bytes', a.size_bytes, 'width', a.width, 'height', a.height,
      'created_at', m.created_at,
      'author', (select jsonb_build_object('first_name', pr.first_name, 'last_name', pr.last_name) from public.profiles pr where pr.id = m.author_id)
    ) as x
    from public.message_attachments a
    join public.messages m on m.id = a.message_id
    where m.channel_id = p_channel
      and m.deleted_at is null
      and (p_before is null or m.created_at < p_before)
      -- Same rule as the app: photos are the compressed JPEGs it creates (with a size); everything else is a file.
      and case when p_kind = 'files' then not (a.mime_type = 'image/jpeg' and a.width is not null)
               else (a.mime_type = 'image/jpeg' and a.width is not null) end
    order by m.created_at desc, a.id desc
    limit least(greatest(coalesce(p_limit, 60), 1), 200)
  ) s
$$;
revoke all on function public.get_channel_media(uuid, text, timestamptz, integer) from public, anon;
grant execute on function public.get_channel_media(uuid, text, timestamptz, integer) to authenticated;


-- >>>>>>>>>>>>>>>>>>>> 20261201000020_material_requests.sql
-- =====================================================================
-- Orion Projects — 0020 Material requests
--
-- Workers request materials for a project (items, quantities, needed-by date,
-- photos). The project's managers mark them Ordered (supplier, PO number,
-- expected date), Delivered or Partly delivered, or Rejected. Everyone involved
-- is notified along the way. Visible only to people on the project.
-- =====================================================================

create table public.material_requests (
  id            uuid primary key,                     -- chosen by the phone, so offline retries never duplicate
  project_id    uuid not null references public.projects (id) on delete cascade,
  number        integer not null,
  requested_by  uuid not null references public.profiles (id) on delete cascade default auth.uid(),
  status        text not null default 'requested'
                check (status in ('requested', 'ordered', 'partly_delivered', 'delivered', 'rejected', 'cancelled')),
  needed_by     date,
  urgent        boolean not null default false,
  delivery_note text check (char_length(delivery_note) <= 1000),
  supplier      text check (char_length(supplier) <= 200),
  po_number     text check (char_length(po_number) <= 100),
  expected_date date,
  reject_reason text check (char_length(reject_reason) <= 500),
  copied_from   uuid references public.material_requests (id) on delete set null,
  ordered_at    timestamptz,
  delivered_at  timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  unique (project_id, number)
);
create index material_requests_project_idx on public.material_requests (project_id, created_at desc);
create index material_requests_open_idx on public.material_requests (status, needed_by) where status in ('requested', 'ordered', 'partly_delivered');
create trigger material_requests_touch before update on public.material_requests
  for each row execute function app.touch_updated_at();

create table public.material_request_items (
  id            uuid primary key default gen_random_uuid(),
  request_id    uuid not null references public.material_requests (id) on delete cascade,
  position      integer not null default 0,
  name          text not null check (char_length(name) between 1 and 200),
  quantity      numeric(12, 2) not null check (quantity > 0),
  unit          text not null default 'pcs' check (char_length(unit) between 1 and 20),
  note          text check (char_length(note) <= 300),
  delivered_qty numeric(12, 2) not null default 0 check (delivered_qty >= 0)
);
create index material_items_request_idx on public.material_request_items (request_id, position);

create table public.material_request_photos (
  id           uuid primary key,
  request_id   uuid not null references public.material_requests (id) on delete cascade,
  project_id   uuid not null references public.projects (id) on delete cascade,
  storage_path text not null unique,
  width        integer,
  height       integer,
  size_bytes   bigint,
  uploaded_by  uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at   timestamptz not null default now()
);
create index material_photos_request_idx on public.material_request_photos (request_id);

create table public.material_request_comments (
  id         uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.material_requests (id) on delete cascade,
  author_id  uuid not null references public.profiles (id) on delete cascade default auth.uid(),
  body       text not null check (char_length(body) between 1 and 4000),
  created_at timestamptz not null default now()
);
create index material_comments_request_idx on public.material_request_comments (request_id, created_at);

-- History (written by triggers only).
create table public.material_request_events (
  id         uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.material_requests (id) on delete cascade,
  actor_id   uuid references public.profiles (id) on delete set null,
  kind       text not null,
  detail     text,
  created_at timestamptz not null default now()
);
create index material_events_request_idx on public.material_request_events (request_id, created_at);

-- ---------------------------------------------------------------- helpers
create or replace function app.material_project(p_request uuid)
returns uuid language sql stable security definer set search_path = ''
as $$ select project_id from public.material_requests where id = p_request $$;

-- Who may change a request's items: the project's managers, or the requester while it's still "requested".
create or replace function app.can_edit_material_items(p_request uuid)
returns boolean language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.material_requests r
    where r.id = p_request
      and (app.can_manage_project(r.project_id)
           or (r.requested_by = auth.uid() and r.status = 'requested' and app.can_edit_project(r.project_id)))
  )
$$;

-- Per-project numbers (#1, #2 …) and the rules for who may change what.
-- Runs as the caller (not "security definer"), so app.is_service_role() tells the server apart from people.
create or replace function app.material_request_before()
returns trigger language plpgsql security invoker set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    select coalesce(max(number), 0) + 1 into new.number from public.material_requests where project_id = new.project_id;
    new.status := 'requested';
    new.supplier := null; new.po_number := null; new.expected_date := null; new.reject_reason := null;
    new.ordered_at := null; new.delivered_at := null;
    return new;
  end if;

  new.id := old.id; new.project_id := old.project_id; new.number := old.number;
  new.requested_by := old.requested_by; new.created_at := old.created_at; new.copied_from := old.copied_from;
  if not app.is_service_role() and not app.can_manage_project(old.project_id) then
    -- The requester (not a manager): only while it's still "requested", and only their own details or cancelling.
    if old.status <> 'requested' then
      raise exception 'This request is already being handled — ask a manager to change it.' using errcode = '42501';
    end if;
    if new.status not in ('requested', 'cancelled') then
      raise exception 'Only managers can mark requests ordered, delivered or rejected.' using errcode = '42501';
    end if;
    new.supplier := old.supplier; new.po_number := old.po_number; new.expected_date := old.expected_date;
    new.reject_reason := old.reject_reason;
  end if;
  if new.status = 'ordered' and old.status <> 'ordered' then new.ordered_at := coalesce(new.ordered_at, now()); end if;
  if new.status = 'delivered' and old.status <> 'delivered' then new.delivered_at := now(); end if;
  if new.status <> 'rejected' then new.reject_reason := null; end if;
  return new;
end;
$$;
create trigger material_requests_before before insert or update on public.material_requests
  for each row execute function app.material_request_before();

-- Only managers record how much was delivered.
-- Runs as the caller (not "security definer"), so app.is_service_role() tells the server apart from people.
create or replace function app.material_item_guard()
returns trigger language plpgsql security invoker set search_path = ''
as $$
begin
  if not app.is_service_role() and not app.can_manage_project(app.material_project(new.request_id)) then
    new.delivered_qty := case when tg_op = 'UPDATE' then old.delivered_qty else 0 end;
  end if;
  if tg_op = 'UPDATE' then new.request_id := old.request_id; end if;
  return new;
end;
$$;
create trigger material_items_guard before insert or update on public.material_request_items
  for each row execute function app.material_item_guard();

-- ---------------------------------------------------------------- RLS
alter table public.material_requests          enable row level security;
alter table public.material_request_items     enable row level security;
alter table public.material_request_photos    enable row level security;
alter table public.material_request_comments  enable row level security;
alter table public.material_request_events    enable row level security;

create policy "materials: read if project visible" on public.material_requests
  for select to authenticated using (app.can_view_project(project_id));
create policy "materials: editors request as themselves" on public.material_requests
  for insert to authenticated with check (requested_by = auth.uid() and app.can_edit_project(project_id));
create policy "materials: managers or requester update" on public.material_requests
  for update to authenticated
  using (app.can_manage_project(project_id) or (requested_by = auth.uid() and app.can_edit_project(project_id)))
  with check (app.can_manage_project(project_id) or (requested_by = auth.uid() and app.can_edit_project(project_id)));
create policy "materials: managers delete" on public.material_requests
  for delete to authenticated using (app.can_manage_project(project_id));

create policy "material items: read" on public.material_request_items
  for select to authenticated using (app.can_view_project(app.material_project(request_id)));
create policy "material items: write" on public.material_request_items
  for all to authenticated using (app.can_edit_material_items(request_id)) with check (app.can_edit_material_items(request_id));

create policy "material photos: read" on public.material_request_photos
  for select to authenticated using (app.can_view_project(project_id));
create policy "material photos: add" on public.material_request_photos
  for insert to authenticated with check (
    uploaded_by = auth.uid() and project_id = app.material_project(request_id) and app.can_edit_project(project_id)
  );
create policy "material photos: uploader or manager delete" on public.material_request_photos
  for delete to authenticated using (uploaded_by = auth.uid() or app.can_manage_project(project_id));

create policy "material comments: read" on public.material_request_comments
  for select to authenticated using (app.can_view_project(app.material_project(request_id)));
create policy "material comments: post" on public.material_request_comments
  for insert to authenticated with check (author_id = auth.uid() and app.can_edit_project(app.material_project(request_id)));
create policy "material comments: author or admin delete" on public.material_request_comments
  for delete to authenticated using (author_id = auth.uid() or app.is_admin());

create policy "material events: read" on public.material_request_events
  for select to authenticated using (app.can_view_project(app.material_project(request_id)));

grant select, insert, update, delete on public.material_requests, public.material_request_items,
  public.material_request_photos, public.material_request_comments to authenticated;
grant select on public.material_request_events to authenticated;
grant all on public.material_requests, public.material_request_items, public.material_request_photos,
  public.material_request_comments, public.material_request_events to service_role;

-- ---------------------------------------------------------------- notifications & history
create or replace function app.material_summary(p_request uuid)
returns text language sql stable security definer set search_path = ''
as $$
  select coalesce(string_agg(i.name || ' ×' || trim(to_char(i.quantity, 'FM999999990.##')) || ' ' || i.unit, ', ' order by i.position)
           filter (where i.rn <= 3), '')
         || case when count(*) > 3 then ' (+' || (count(*) - 3) || ' more)' else '' end
  from (select it.*, row_number() over (order by it.position) as rn from public.material_request_items it where it.request_id = p_request) i
$$;

-- New request (at the end of the transaction, once its items exist) → the project's managers.
create or replace function app.on_material_request_created()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare
  p public.projects%rowtype;
  who text := app.person_name(new.requested_by);
  link text := '/projects/' || new.project_id || '/materials?request=' || new.id;
  u uuid;
  title text;
begin
  select * into p from public.projects where id = new.project_id;
  title := case when new.urgent then '🚨 Urgent material request' else 'Material request' end
           || ' #' || new.number || ' from ' || who || ' · ' || p.name;
  insert into public.material_request_events (request_id, actor_id, kind) values (new.id, new.requested_by, 'created');
  for u in
    select m.user_id from public.project_members m join public.profiles pr on pr.id = m.user_id
    where m.project_id = new.project_id and pr.role in ('admin', 'manager')
    union
    -- Nobody to handle it on the project? Tell the administrators.
    select pr.id from public.profiles pr
    where pr.role = 'admin' and pr.status = 'active'
      and not exists (select 1 from public.project_members m join public.profiles x on x.id = m.user_id
                      where m.project_id = new.project_id and x.role in ('admin', 'manager'))
  loop
    perform app.notify(u, 'material.new', title,
      app.material_summary(new.id) || case when new.needed_by is not null then ' · needed by ' || to_char(new.needed_by, 'FMDD Mon') else '' end,
      link, new.project_id, null, new.requested_by);
  end loop;
  return null;
end;
$$;
create constraint trigger material_requests_created after insert on public.material_requests
  deferrable initially deferred
  for each row execute function app.on_material_request_created();

-- Status changes → history + the requester.
create or replace function app.on_material_request_status()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare
  link text := '/projects/' || new.project_id || '/materials?request=' || new.id;
  label text;
  body text;
begin
  if new.status = old.status then
    return null;
  end if;
  label := case new.status
    when 'ordered' then 'was ordered'
    when 'partly_delivered' then 'was partly delivered'
    when 'delivered' then 'was delivered'
    when 'rejected' then 'was rejected'
    when 'cancelled' then 'was cancelled'
    else 'was reopened' end;
  body := case new.status
    when 'ordered' then concat_ws(' · ', nullif(new.supplier, ''), case when new.expected_date is not null then 'expected ' || to_char(new.expected_date, 'FMDD Mon') end, case when new.po_number is not null then 'PO ' || new.po_number end)
    when 'rejected' then new.reject_reason
    else null end;
  insert into public.material_request_events (request_id, actor_id, kind, detail) values (new.id, auth.uid(), new.status, nullif(body, ''));
  perform app.notify(new.requested_by, 'material.status', 'Your material request #' || new.number || ' ' || label,
    coalesce(nullif(body, ''), app.material_summary(new.id)), link, new.project_id, null, auth.uid());
  return null;
end;
$$;
create trigger material_requests_status after update of status on public.material_requests
  for each row execute function app.on_material_request_status();

-- Comments → the requester and the project's managers (not the writer).
create or replace function app.on_material_comment()
returns trigger language plpgsql security definer set search_path = ''
as $$
declare
  r public.material_requests%rowtype;
  u uuid;
begin
  select * into r from public.material_requests where id = new.request_id;
  for u in
    select r.requested_by
    union
    select m.user_id from public.project_members m join public.profiles pr on pr.id = m.user_id
    where m.project_id = r.project_id and pr.role in ('admin', 'manager')
  loop
    perform app.notify(u, 'material.comment', app.person_name(new.author_id) || ' commented on material request #' || r.number,
      left(new.body, 200), '/projects/' || r.project_id || '/materials?request=' || r.id, r.project_id, null, new.author_id);
  end loop;
  return null;
end;
$$;
create trigger material_comments_notify after insert on public.material_request_comments
  for each row execute function app.on_material_comment();

-- ---------------------------------------------------------------- functions for the app
-- Creates a request with its items in one go. Safe to repeat (the phone retries offline requests).
create or replace function public.create_material_request(
  p_id uuid, p_project uuid, p_needed_by date, p_urgent boolean, p_note text, p_items jsonb, p_copied_from uuid default null
)
returns jsonb
language plpgsql volatile security invoker
set search_path = ''
as $$
declare
  existing public.material_requests%rowtype;
  r public.material_requests%rowtype;
begin
  select * into existing from public.material_requests where id = p_id;
  if found then
    if existing.requested_by <> auth.uid() then
      raise exception 'This request could not be saved. Please try again.';
    end if;
    return jsonb_build_object('id', existing.id, 'number', existing.number, 'project_id', existing.project_id);
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Add at least one item';
  end if;
  if jsonb_array_length(p_items) > 100 then
    raise exception 'A request can have up to 100 items';
  end if;

  insert into public.material_requests (id, project_id, requested_by, needed_by, urgent, delivery_note, copied_from)
  values (p_id, p_project, auth.uid(), p_needed_by, coalesce(p_urgent, false), nullif(trim(p_note), ''), p_copied_from)
  returning * into r;

  insert into public.material_request_items (request_id, position, name, quantity, unit, note)
  select r.id, x.ord::integer, trim(x.v->>'name'), (x.v->>'quantity')::numeric, coalesce(nullif(trim(x.v->>'unit'), ''), 'pcs'), nullif(trim(x.v->>'note'), '')
  from jsonb_array_elements(p_items) with ordinality as x(v, ord);

  return jsonb_build_object('id', r.id, 'number', r.number, 'project_id', r.project_id);
end;
$$;

-- List of requests: one project, or every project you can see.
create or replace function public.get_material_requests(p_project uuid default null, p_open_only boolean default false)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(x order by (x->>'sort_group')::int, x->>'sort_date', (x->>'number')::int desc), '[]')
  from (
    select jsonb_build_object(
      'id', r.id, 'number', r.number, 'status', r.status, 'needed_by', r.needed_by, 'urgent', r.urgent,
      'supplier', r.supplier, 'po_number', r.po_number, 'expected_date', r.expected_date,
      'created_at', r.created_at, 'updated_at', r.updated_at, 'delivered_at', r.delivered_at,
      'project', jsonb_build_object('id', p.id, 'name', p.name, 'color', p.color),
      'requested_by', jsonb_build_object('id', pr.id, 'first_name', pr.first_name, 'last_name', pr.last_name),
      'item_count', (select count(*) from public.material_request_items i where i.request_id = r.id),
      'summary', app.material_summary(r.id),
      'photo_count', (select count(*) from public.material_request_photos f where f.request_id = r.id),
      'comment_count', (select count(*) from public.material_request_comments c where c.request_id = r.id),
      'late', r.status in ('requested', 'ordered', 'partly_delivered') and r.needed_by is not null and r.needed_by < public.malta_today(),
      'sort_group', case when r.status in ('requested', 'ordered', 'partly_delivered') then 0 else 1 end,
      'sort_date', case when r.status in ('requested', 'ordered', 'partly_delivered') then coalesce(r.needed_by::text, '9999') else to_char(9999999999 - extract(epoch from r.updated_at), 'FM0000000000') end
    ) as x
    from public.material_requests r
    join public.projects p on p.id = r.project_id
    left join public.profiles pr on pr.id = r.requested_by
    where (p_project is null or r.project_id = p_project)
      and (not p_open_only or r.status in ('requested', 'ordered', 'partly_delivered'))
    order by r.created_at desc
    limit 500
  ) s
$$;

-- One request with everything: items, photos, comments and history.
create or replace function public.get_material_request(p_id uuid)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select to_jsonb(r) || jsonb_build_object(
    'project', jsonb_build_object('id', p.id, 'name', p.name, 'color', p.color, 'code', p.code,
                 'client', (select c.name from public.clients c where c.id = p.client_id)),
    'requester', (select jsonb_build_object('id', pr.id, 'first_name', pr.first_name, 'last_name', pr.last_name, 'phone', pr.phone, 'email', pr.email) from public.profiles pr where pr.id = r.requested_by),
    'items', coalesce((select jsonb_agg(to_jsonb(i) order by i.position) from public.material_request_items i where i.request_id = r.id), '[]'),
    'photos', coalesce((select jsonb_agg(jsonb_build_object('id', f.id, 'storage_path', f.storage_path, 'width', f.width, 'height', f.height) order by f.created_at) from public.material_request_photos f where f.request_id = r.id), '[]'),
    'comments', coalesce((select jsonb_agg(jsonb_build_object('id', c.id, 'body', c.body, 'created_at', c.created_at, 'author_id', c.author_id,
                   'author', (select jsonb_build_object('first_name', a.first_name, 'last_name', a.last_name) from public.profiles a where a.id = c.author_id)) order by c.created_at)
                 from public.material_request_comments c where c.request_id = r.id), '[]'),
    'events', coalesce((select jsonb_agg(jsonb_build_object('kind', e.kind, 'detail', e.detail, 'created_at', e.created_at,
                   'actor', (select jsonb_build_object('first_name', a.first_name, 'last_name', a.last_name) from public.profiles a where a.id = e.actor_id)) order by e.created_at)
                 from public.material_request_events e where e.request_id = r.id), '[]')
  )
  from public.material_requests r
  join public.projects p on p.id = r.project_id
  where r.id = p_id
$$;

-- Everything delivered to a project so far, added up per material.
create or replace function public.get_project_materials(p_project uuid)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  select coalesce(jsonb_agg(x order by x->>'name'), '[]')
  from (
    select jsonb_build_object(
      'name', min(i.name), 'unit', i.unit,
      'delivered', sum(i.delivered_qty),
      'requested', sum(i.quantity),
      'last_delivered', max(coalesce(r.delivered_at, r.updated_at)),
      'requests', jsonb_agg(distinct r.number)
    ) as x
    from public.material_request_items i
    join public.material_requests r on r.id = i.request_id
    where r.project_id = p_project and i.delivered_qty > 0
    group by lower(trim(i.name)), i.unit
  ) s
$$;

revoke all on function public.create_material_request(uuid, uuid, date, boolean, text, jsonb, uuid) from public, anon;
revoke all on function public.get_material_requests(uuid, boolean) from public, anon;
revoke all on function public.get_material_request(uuid) from public, anon;
revoke all on function public.get_project_materials(uuid) from public, anon;
grant execute on function public.create_material_request(uuid, uuid, date, boolean, text, jsonb, uuid) to authenticated;
grant execute on function public.get_material_requests(uuid, boolean) to authenticated;
grant execute on function public.get_material_request(uuid) to authenticated;
grant execute on function public.get_project_materials(uuid) to authenticated;
grant execute on all functions in schema app to authenticated, service_role;

-- ---------------------------------------------------------------- daily reminder
create or replace function public.create_due_notifications()
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare
  today date := public.malta_today();
  r record;
  n integer := 0;
  kind text;
  v_title text;
begin
  for r in
    select t.id, t.title, t.project_id, t.due_date, a.user_id
    from public.tasks t
    join public.task_assignees a on a.task_id = t.id
    join public.projects p on p.id = t.project_id
    where t.completed_at is null and p.status = 'active' and not p.is_template
      and t.due_date is not null and t.due_date <= today + 1
      and t.due_date >= today - 1
  loop
    kind := case when r.due_date < today then 'task.overdue' else 'task.due_soon' end;
    v_title := case when r.due_date < today then 'Overdue: ' when r.due_date = today then 'Due today: ' else 'Due tomorrow: ' end || r.title;
    if not exists (
      select 1 from public.notifications x
      where x.user_id = r.user_id and x.task_id = r.id and x.type = kind and x.created_at > now() - interval '20 hours'
    ) then
      perform app.notify(r.user_id, kind, v_title, null, '/projects/' || r.project_id || '/board?task=' || r.id, r.project_id, r.id, null);
      n := n + 1;
    end if;
  end loop;

  -- Personal to-dos (the notification text is only ever sent to the owner).
  for r in
    select pt.id, pt.title, pt.due_date, pt.user_id
    from public.personal_todos pt
    where pt.done_at is null and pt.due_date is not null and pt.due_date between today and today + 1
  loop
    v_title := case when r.due_date = today then 'Due today: ' else 'Due tomorrow: ' end || r.title;
    if not exists (
      select 1 from public.notifications x
      where x.user_id = r.user_id and x.type = 'personal.due' and x.title = left(v_title, 200) and x.created_at > now() - interval '20 hours'
    ) then
      perform app.notify(r.user_id, 'personal.due', v_title, 'Personal to-do', '/personal', null, null, null);
      n := n + 1;
    end if;
  end loop;

  -- Materials needed today or tomorrow that nobody has ordered yet → the project's managers.
  for r in
    select mr.id, mr.number, mr.project_id, mr.needed_by, p.name as project_name, m.user_id
    from public.material_requests mr
    join public.projects p on p.id = mr.project_id
    join public.project_members m on m.project_id = mr.project_id
    join public.profiles pr on pr.id = m.user_id and pr.role in ('admin', 'manager')
    where mr.status = 'requested' and mr.needed_by between today and today + 1
  loop
    v_title := 'Material needed ' || case when r.needed_by = today then 'today' else 'tomorrow' end
               || ', not ordered yet: #' || r.number || ' · ' || r.project_name;
    if not exists (
      select 1 from public.notifications x
      where x.user_id = r.user_id and x.type = 'material.status' and x.title = left(v_title, 200) and x.created_at > now() - interval '20 hours'
    ) then
      perform app.notify(r.user_id, 'material.status', v_title, null, '/projects/' || r.project_id || '/materials?request=' || r.id, r.project_id, null, null);
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$$;
revoke all on function public.create_due_notifications() from public, anon, authenticated;
grant execute on function public.create_due_notifications() to service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261202000021_products.sql
-- =====================================================================
-- Orion Projects — 0021 Product catalogue for material requests
--
-- Managers keep a list of products (name, unit, category, code). Workers pick
-- from it when requesting materials (they can still type a one-off item).
-- Request items are linked to products, so a project's materials report can
-- add up exactly what was delivered.
-- =====================================================================

create table public.products (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (char_length(trim(name)) between 1 and 200),
  unit       text not null default 'pcs' check (char_length(unit) between 1 and 20),
  category   text check (char_length(category) <= 60),
  code       text check (char_length(code) <= 60),
  active     boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
-- The same product name can't be listed twice with the same unit.
create unique index products_name_unit_idx on public.products (lower(trim(name)), unit);
create index products_category_idx on public.products (category, name) where active;
create trigger products_touch before update on public.products
  for each row execute function app.touch_updated_at();

alter table public.products enable row level security;
create policy "products: everyone signed in reads" on public.products
  for select to authenticated using (app.is_active());
create policy "products: managers add" on public.products
  for insert to authenticated with check (app.is_manager_or_above());
create policy "products: managers edit" on public.products
  for update to authenticated using (app.is_manager_or_above()) with check (app.is_manager_or_above());
create policy "products: admins delete" on public.products
  for delete to authenticated using (app.is_admin());
grant select, insert, update, delete on public.products to authenticated;
grant all on public.products to service_role;

-- Request items can point at a product.
alter table public.material_request_items
  add column product_id uuid references public.products (id) on delete set null;
create index material_items_product_idx on public.material_request_items (product_id) where product_id is not null;

-- A typed item whose name and unit exactly match a product is linked to it automatically.
create or replace function app.material_item_link_product()
returns trigger language plpgsql security invoker set search_path = ''
as $$
begin
  if new.product_id is null then
    select p.id into new.product_id from public.products p
    where p.active and lower(trim(p.name)) = lower(trim(new.name)) and p.unit = new.unit
    limit 1;
  end if;
  return new;
end;
$$;
create trigger material_items_link_product before insert or update of name, unit, product_id on public.material_request_items
  for each row execute function app.material_item_link_product();

-- Adding (or renaming) a product links earlier items that were typed with the same name and unit.
create or replace function app.product_link_items()
returns trigger language plpgsql security definer set search_path = ''
as $$
begin
  if new.active then
    update public.material_request_items i set product_id = new.id
    where i.product_id is null and lower(trim(i.name)) = lower(trim(new.name)) and i.unit = new.unit;
  end if;
  return null;
end;
$$;
create trigger products_link_items after insert or update of name, unit, active on public.products
  for each row execute function app.product_link_items();

-- Creating a request now also records the chosen products.
create or replace function public.create_material_request(
  p_id uuid, p_project uuid, p_needed_by date, p_urgent boolean, p_note text, p_items jsonb, p_copied_from uuid default null
)
returns jsonb
language plpgsql volatile security invoker
set search_path = ''
as $$
declare
  existing public.material_requests%rowtype;
  r public.material_requests%rowtype;
begin
  select * into existing from public.material_requests where id = p_id;
  if found then
    if existing.requested_by <> auth.uid() then
      raise exception 'This request could not be saved. Please try again.';
    end if;
    return jsonb_build_object('id', existing.id, 'number', existing.number, 'project_id', existing.project_id);
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Add at least one item';
  end if;
  if jsonb_array_length(p_items) > 100 then
    raise exception 'A request can have up to 100 items';
  end if;

  insert into public.material_requests (id, project_id, requested_by, needed_by, urgent, delivery_note, copied_from)
  values (p_id, p_project, auth.uid(), p_needed_by, coalesce(p_urgent, false), nullif(trim(p_note), ''), p_copied_from)
  returning * into r;

  insert into public.material_request_items (request_id, position, name, quantity, unit, note, product_id)
  select r.id, x.ord::integer, trim(x.v->>'name'), (x.v->>'quantity')::numeric, coalesce(nullif(trim(x.v->>'unit'), ''), 'pcs'), nullif(trim(x.v->>'note'), ''),
         -- Chosen from the product list (ignored if that product no longer exists).
         (select p.id from public.products p where p.id::text = nullif(x.v->>'product_id', ''))
  from jsonb_array_elements(p_items) with ordinality as x(v, ord);

  return jsonb_build_object('id', r.id, 'number', r.number, 'project_id', r.project_id);
end;
$$;

-- Materials report for a project: what was delivered (optionally between two dates), per product.
-- Items typed by hand (not in the catalogue) are listed by their name and unit.
create or replace function public.get_material_report(p_project uuid, p_from date default null, p_to date default null)
returns jsonb
language sql stable security invoker
set search_path = ''
as $$
  with lines as (
    select i.*, r.number,
           p.name as product_name, p.category, p.code,
           (coalesce(r.delivered_at,
                     (select max(e.created_at) from public.material_request_events e
                      where e.request_id = r.id and e.kind in ('delivered', 'partly_delivered')),
                     r.updated_at) at time zone 'Europe/Malta')::date as delivered_on
    from public.material_request_items i
    join public.material_requests r on r.id = i.request_id
    left join public.products p on p.id = i.product_id
    where r.project_id = p_project and r.status not in ('rejected', 'cancelled') and i.delivered_qty > 0
  )
  select coalesce(jsonb_agg(x order by x->>'category' nulls last, x->>'name'), '[]')
  from (
    select jsonb_build_object(
      'product_id', min(product_id::text),
      'name', coalesce(min(product_name), min(name)),
      'unit', min(unit),
      'category', min(category),
      'code', min(code),
      'in_catalogue', bool_or(product_id is not null),
      'delivered', sum(delivered_qty),
      'requested', sum(quantity),
      'requests', jsonb_agg(distinct number),
      'first_delivered', min(delivered_on),
      'last_delivered', max(delivered_on)
    ) as x
    from lines
    where (p_from is null or delivered_on >= p_from) and (p_to is null or delivered_on <= p_to)
    group by coalesce(product_id::text, 'typed:' || lower(trim(name)) || '|' || unit)
  ) s
$$;
revoke all on function public.get_material_report(uuid, date, date) from public, anon;
grant execute on function public.get_material_report(uuid, date, date) to authenticated;
grant execute on all functions in schema app to authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261203000022_task_order.sql
-- =====================================================================
-- Orion Projects — 0022 Task order: insert a task between others, and move tasks
--
-- move_task: puts a task in a group, just before another task (or at the end).
-- insert_task_at: adds a new task right above or below an existing one. If they
-- are linked ("waiting for"), the chain is rewired A → new → B. Later tasks'
-- dates are NOT moved (the Gantt shows a warning if they now clash).
-- Both run as the caller, so the usual permissions apply.
-- =====================================================================

create or replace function public.move_task(p_task uuid, p_group uuid, p_before uuid default null)
returns void
language plpgsql volatile security invoker
set search_path = ''
as $$
declare
  t public.tasks%rowtype;
  g public.groups%rowtype;
  ids uuid[];
  idx integer;
  i integer;
begin
  select * into t from public.tasks where id = p_task;
  if not found then raise exception 'Task not found'; end if;
  select * into g from public.groups where id = p_group;
  if not found or g.project_id <> t.project_id then raise exception 'That group is in another project'; end if;
  if p_before is not null and not exists (select 1 from public.tasks where id = p_before and group_id = p_group) then
    raise exception 'The task to place it before is not in that group';
  end if;

  -- The group's tasks in their current order, without the one being moved…
  select coalesce(array_agg(x.id order by x.position, x.created_at), '{}') into ids
  from public.tasks x where x.group_id = p_group and x.id <> p_task;
  -- …then slot it in.
  idx := case when p_before is null then coalesce(array_length(ids, 1), 0) + 1 else array_position(ids, p_before) end;
  ids := ids[1:idx - 1] || p_task || ids[idx:];

  -- Number them 1, 2, 3… (only rows whose place actually changes are written).
  for i in 1 .. array_length(ids, 1) loop
    update public.tasks set position = i, group_id = p_group
    where id = ids[i] and (position is distinct from i or group_id is distinct from p_group);
  end loop;
  -- Row-level security silently skips rows the caller can't change: check it really moved.
  if not exists (select 1 from public.tasks where id = p_task and group_id = p_group and position = idx) then
    raise exception 'You can''t move tasks on this project' using errcode = '42501';
  end if;
end;
$$;

create or replace function public.insert_task_at(
  p_anchor uuid, p_where text, p_title text, p_start date default null, p_due date default null, p_rewire boolean default true
)
returns uuid
language plpgsql volatile security invoker
set search_path = ''
as $$
declare
  a public.tasks%rowtype;
  new_id uuid;
  first_status uuid;
  next_id uuid;
  rewired boolean := false;
begin
  if p_where not in ('above', 'below') then raise exception 'Choose above or below'; end if;
  select * into a from public.tasks where id = p_anchor;
  if not found then raise exception 'Task not found'; end if;

  select s.id into first_status from public.status_labels s
  where s.project_id = a.project_id and not s.is_done order by s.position limit 1;

  insert into public.tasks (project_id, group_id, title, status_id, start_date, due_date, position, created_by)
  values (a.project_id, a.group_id, trim(p_title), first_status, p_start, p_due, a.position, auth.uid())
  returning id into new_id;

  -- Place it: above = just before the anchor; below = just before the task after the anchor.
  if p_where = 'above' then
    perform public.move_task(new_id, a.group_id, a.id);
  else
    select x.id into next_id from public.tasks x
    where x.group_id = a.group_id and x.id not in (a.id, new_id)
      and (x.position, x.created_at) > (a.position, a.created_at)
    order by x.position, x.created_at limit 1;
    perform public.move_task(new_id, a.group_id, next_id);
  end if;

  -- Keep the chain of links in order (managers plan links; others just get the task).
  if p_rewire and app.can_manage_project(a.project_id) then
    if p_where = 'below' and exists (select 1 from public.task_dependencies d where d.depends_on_task_id = a.id) then
      -- A → B becomes A → new → B
      update public.task_dependencies set depends_on_task_id = new_id where depends_on_task_id = a.id;
      insert into public.task_dependencies (task_id, depends_on_task_id) values (new_id, a.id);
      rewired := true;
    elsif p_where = 'above' and exists (select 1 from public.task_dependencies d where d.task_id = a.id) then
      -- X → A becomes X → new → A
      insert into public.task_dependencies (task_id, depends_on_task_id)
      select new_id, d.depends_on_task_id from public.task_dependencies d where d.task_id = a.id;
      delete from public.task_dependencies where task_id = a.id;
      insert into public.task_dependencies (task_id, depends_on_task_id) values (a.id, new_id);
      rewired := true;
    end if;
  end if;
  return new_id;
end;
$$;

revoke all on function public.move_task(uuid, uuid, uuid) from public, anon;
revoke all on function public.insert_task_at(uuid, text, text, date, date, boolean) from public, anon;
grant execute on function public.move_task(uuid, uuid, uuid) to authenticated;
grant execute on function public.insert_task_at(uuid, text, text, date, date, boolean) to authenticated;


-- >>>>>>>>>>>>>>>>>>>> 20261204000023_daily_reminder.sql
-- =====================================================================
-- Orion Projects — 0023 Daily update reminder
--
-- On working days at a time administrators choose (default 16:30, Malta
-- time) technicians on active projects who haven't posted today's daily
-- update get a reminder (🔔 + phone notification). Sent once per day.
--
-- Something must wake the app every 15 minutes to check the time: a
-- Supabase scheduled job (pg_cron) calls /api/cron/reminders. Admin → Setup
-- shows the one-time snippet. The job proves who it is with the token in
-- public.job_secrets, so no secret has to be copied around.
-- =====================================================================

alter table public.app_settings
  add column daily_reminder_enabled boolean not null default true,
  add column daily_reminder_time    time    not null default '16:30',
  add column daily_reminder_sent_on date,
  add column reminder_checked_at    timestamptz;

-- Token the scheduled job sends with each call. Only the server can read it.
create table public.job_secrets (
  name  text primary key,
  token text not null
);
alter table public.job_secrets enable row level security;
revoke all on public.job_secrets from public, anon, authenticated;
grant all on public.job_secrets to service_role;
insert into public.job_secrets (name, token)
values ('reminders', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
on conflict (name) do nothing;

-- Called every ~15 minutes. Sends the reminders once, when the chosen time has
-- come on a working day (and up to 3 hours after, in case a check was missed).
-- Returns how many people were reminded.
create or replace function public.queue_daily_update_reminders(p_now timestamptz default now())
returns integer
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  s        public.app_settings%rowtype;
  local_ts timestamp := p_now at time zone 'Europe/Malta';
  today    date := (p_now at time zone 'Europe/Malta')::date;
  n        integer := 0;
  r        record;
begin
  update public.app_settings set reminder_checked_at = p_now where id returning * into s;

  if not s.daily_reminder_enabled
     or s.daily_reminder_sent_on is not distinct from today
     or not (extract(isodow from today)::smallint = any (s.daily_update_weekdays))
     or local_ts::time < s.daily_reminder_time
     or local_ts::time > s.daily_reminder_time + interval '3 hours' then
    return 0;
  end if;

  update public.app_settings set daily_reminder_sent_on = today where id;

  for r in
    select pr.id
    from public.profiles pr
    where pr.role = 'technician' and pr.status = 'active'
      and exists (
        select 1 from public.project_members pm
        join public.projects p on p.id = pm.project_id
        where pm.user_id = pr.id and p.status = 'active' and not p.is_template
      )
      and not exists (
        select 1 from public.daily_updates du where du.author_id = pr.id and du.work_date = today
      )
  loop
    perform app.notify(
      r.id, 'daily.reminder',
      'Time to post today''s daily update',
      'What did you do today? Add a few words and photos — it only takes a minute.',
      '/daily-update', null, null, null
    );
    n := n + 1;
  end loop;
  return n;
end;
$$;

revoke all on function public.queue_daily_update_reminders(timestamptz) from public, anon, authenticated;
grant execute on function public.queue_daily_update_reminders(timestamptz) to service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261205000024_user_activity.sql
-- =====================================================================
-- Orion Projects — 0024 Who is using the app (Admin → Activity)
--
-- The app notes when each person last opened it ("last active"), at most
-- once every 5 minutes. Only the time is kept — not what they looked at.
-- Only administrators can see it, through get_user_activity().
-- =====================================================================

create table public.user_activity (
  user_id      uuid primary key references public.profiles (id) on delete cascade,
  last_seen_at timestamptz not null default now()
);
alter table public.user_activity enable row level security;
-- No policies: nobody reads or writes it directly. The functions below do.
revoke all on public.user_activity from public, anon, authenticated;
grant all on public.user_activity to service_role;

-- Called by the app when someone opens it or comes back to it.
create or replace function public.touch_last_seen()
returns void
language sql volatile security definer
set search_path = ''
as $$
  insert into public.user_activity (user_id, last_seen_at)
  select auth.uid(), now()
  where auth.uid() is not null
  on conflict (user_id) do update set last_seen_at = excluded.last_seen_at
  where public.user_activity.last_seen_at < now() - interval '5 minutes';
$$;

-- Administrators: everyone (except people still waiting for approval) with
-- last active time, last daily update and whether phone notifications are on.
create or replace function public.get_user_activity()
returns jsonb
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not app.is_admin() then
    raise exception 'Only administrators can see activity' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', pr.id,
      'first_name', pr.first_name,
      'last_name', pr.last_name,
      'email', pr.email,
      'avatar_url', pr.avatar_url,
      'role', pr.role,
      'status', pr.status,
      'joined_at', pr.created_at,
      'last_seen_at', ua.last_seen_at,
      'last_update', (select max(du.work_date) from public.daily_updates du where du.author_id = pr.id),
      'push_on', exists (select 1 from public.push_subscriptions ps where ps.user_id = pr.id)
                 and not exists (select 1 from public.notification_preferences np where np.user_id = pr.id and not np.push_enabled),
      'projects', coalesce((
        select jsonb_agg(p.name order by p.name)
        from public.project_members pm join public.projects p on p.id = pm.project_id
        where pm.user_id = pr.id and p.status = 'active' and not p.is_template
      ), '[]'::jsonb)
    ) order by ua.last_seen_at asc nulls first, pr.first_name)
    from public.profiles pr
    left join public.user_activity ua on ua.user_id = pr.id
    where pr.status <> 'pending'
  ), '[]'::jsonb);
end;
$$;

revoke all on function public.touch_last_seen() from public, anon;
grant execute on function public.touch_last_seen() to authenticated, service_role;
revoke all on function public.get_user_activity() from public, anon;
grant execute on function public.get_user_activity() to authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261206000025_announcements.sql
-- =====================================================================
-- Orion Projects — 0025 Important messages (administrators only)
--
-- An administrator sends a message to chosen people. Each person gets a
-- phone notification that stays on screen, and a full-screen message in
-- the app that they must confirm ("I've read this"). Administrators see who
-- has read it. Unread messages are sent again every few hours (working
-- hours, for up to 3 days) by the 15-minute job (/api/cron/reminders).
-- =====================================================================

create table public.announcements (
  id                 uuid primary key default gen_random_uuid(),
  title              text not null check (char_length(trim(title)) between 1 and 120),
  body               text not null check (char_length(trim(body)) between 1 and 4000),
  remind_every_hours smallint check (remind_every_hours is null or remind_every_hours between 1 and 24),
  created_by         uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at         timestamptz not null default now()
);

create table public.announcement_recipients (
  announcement_id uuid not null references public.announcements (id) on delete cascade,
  user_id         uuid not null references public.profiles (id) on delete cascade,
  read_at         timestamptz,
  last_sent_at    timestamptz not null default now(),
  times_sent      smallint not null default 1,
  primary key (announcement_id, user_id)
);
create index announcement_recipients_unread_idx on public.announcement_recipients (user_id) where read_at is null;

alter table public.announcements enable row level security;
alter table public.announcement_recipients enable row level security;

-- Read: administrators see everything; everyone else only messages sent to them.
create policy "announcements: admins read" on public.announcements
  for select to authenticated using (app.is_admin());
create policy "announcements: recipients read" on public.announcements
  for select to authenticated using (
    exists (select 1 from public.announcement_recipients r where r.announcement_id = announcements.id and r.user_id = auth.uid())
  );
create policy "announcements: admins delete" on public.announcements
  for delete to authenticated using (app.is_admin());
create policy "announcement recipients: admins read" on public.announcement_recipients
  for select to authenticated using (app.is_admin());
create policy "announcement recipients: own row" on public.announcement_recipients
  for select to authenticated using (user_id = auth.uid());
-- No insert/update policies: sending and "I've read this" go through the functions below.
revoke all on public.announcements, public.announcement_recipients from public, anon, authenticated;
grant select, delete on public.announcements to authenticated;
grant select on public.announcement_recipients to authenticated;
grant all on public.announcements, public.announcement_recipients to service_role;

-- Administrators: send a message to these people (active accounts only).
create or replace function public.send_announcement(p_title text, p_body text, p_user_ids uuid[], p_remind_every_hours smallint default 2)
returns uuid
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  a_id uuid;
  r record;
begin
  if not app.is_admin() then
    raise exception 'Only administrators can send important messages' using errcode = '42501';
  end if;
  insert into public.announcements (title, body, remind_every_hours, created_by)
  values (trim(p_title), trim(p_body), p_remind_every_hours, auth.uid())
  returning id into a_id;

  for r in
    select pr.id from public.profiles pr
    where pr.id = any (p_user_ids) and pr.status = 'active'
  loop
    insert into public.announcement_recipients (announcement_id, user_id) values (a_id, r.id);
    -- The sender gets it too if they chose themselves (handy for testing).
    insert into public.notifications (user_id, type, title, body, link, actor_id)
    values (r.id, 'announcement', left('Important: ' || trim(p_title), 200), left(trim(p_body), 1000), '/home?message=' || a_id, auth.uid());
  end loop;

  if not exists (select 1 from public.announcement_recipients where announcement_id = a_id) then
    raise exception 'Choose at least one active person' using errcode = '22023';
  end if;
  return a_id;
end;
$$;

-- "I've read this".
create or replace function public.mark_announcement_read(p_id uuid)
returns void
language sql volatile security definer
set search_path = ''
as $$
  update public.announcement_recipients set read_at = now()
  where announcement_id = p_id and user_id = auth.uid() and read_at is null;
  update public.notifications set read_at = now()
  where user_id = auth.uid() and type = 'announcement' and link = '/home?message=' || p_id and read_at is null;
$$;

-- Every 15 minutes (server only): send unread messages again when it's time,
-- 07:00–19:00 Malta, for up to 3 days and at most 10 times. Returns how many.
create or replace function public.queue_announcement_reminders(p_now timestamptz default now())
returns integer
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  local_time time := (p_now at time zone 'Europe/Malta')::time;
  n integer := 0;
  r record;
begin
  if local_time < '07:00' or local_time > '19:00' then
    return 0;
  end if;
  for r in
    select rc.announcement_id, rc.user_id, a.title, a.body
    from public.announcement_recipients rc
    join public.announcements a on a.id = rc.announcement_id
    join public.profiles pr on pr.id = rc.user_id and pr.status = 'active'
    where rc.read_at is null
      and a.remind_every_hours is not null
      and a.created_at > p_now - interval '3 days'
      and rc.times_sent < 10
      and rc.last_sent_at <= p_now - make_interval(hours => a.remind_every_hours) + interval '2 minutes'
    for update of rc skip locked
  loop
    update public.announcement_recipients set last_sent_at = p_now, times_sent = times_sent + 1
    where announcement_id = r.announcement_id and user_id = r.user_id;
    insert into public.notifications (user_id, type, title, body, link)
    values (r.user_id, 'announcement', left('Reminder – important: ' || r.title, 200), left(r.body, 1000), '/home?message=' || r.announcement_id);
    n := n + 1;
  end loop;
  return n;
end;
$$;

revoke all on function public.send_announcement(text, text, uuid[], smallint) from public, anon;
grant execute on function public.send_announcement(text, text, uuid[], smallint) to authenticated, service_role;
revoke all on function public.mark_announcement_read(uuid) from public, anon;
grant execute on function public.mark_announcement_read(uuid) to authenticated, service_role;
revoke all on function public.queue_announcement_reminders(timestamptz) from public, anon, authenticated;
grant execute on function public.queue_announcement_reminders(timestamptz) to service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261207000026_general_tasks.sql
-- =====================================================================
-- Orion Projects — 0026 General tasks (not linked to a project)
--
-- E.g. "Chase ABC Ltd for the tender update". Managers and administrators
-- create them and assign colleagues; they can be linked to a client.
-- Visible only to the creator, the people assigned, and administrators.
-- Assignees can change the status, tick the checklist and comment; the
-- creator (or an administrator) can change everything else.
-- =====================================================================

create table public.general_tasks (
  id               uuid primary key default gen_random_uuid(),
  title            text not null check (char_length(trim(title)) between 1 and 300),
  description      text check (char_length(description) <= 8000),
  client_id        uuid references public.clients (id) on delete set null,
  status           text not null default 'not_started' check (status in ('not_started', 'working', 'waiting', 'done')),
  priority         public.task_priority not null default 'medium',
  due_date         date,
  checklist        jsonb not null default '[]'::jsonb check (jsonb_typeof(checklist) = 'array' and jsonb_array_length(checklist) <= 100),
  created_by       uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  completed_at     timestamptz
);
create index general_tasks_created_by_idx on public.general_tasks (created_by);

create table public.general_task_assignees (
  task_id uuid not null references public.general_tasks (id) on delete cascade,
  user_id uuid not null references public.profiles (id) on delete cascade,
  added_at timestamptz not null default now(),
  primary key (task_id, user_id)
);
create index general_task_assignees_user_idx on public.general_task_assignees (user_id);

create table public.general_task_comments (
  id         uuid primary key default gen_random_uuid(),
  task_id    uuid not null references public.general_tasks (id) on delete cascade,
  author_id  uuid references public.profiles (id) on delete set null default auth.uid(),
  body       text not null check (char_length(trim(body)) between 1 and 4000),
  created_at timestamptz not null default now()
);
create index general_task_comments_task_idx on public.general_task_comments (task_id, created_at);

-- Who may see / manage a general task (definer: no policy recursion).
create or replace function app.can_see_general_task(p_task uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select app.is_active() and (
    app.is_admin()
    or exists (select 1 from public.general_tasks t where t.id = p_task and t.created_by = auth.uid())
    or exists (select 1 from public.general_task_assignees a where a.task_id = p_task and a.user_id = auth.uid())
  )
$$;

create or replace function app.can_manage_general_task(p_task uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select app.is_active() and (
    app.is_admin()
    or exists (select 1 from public.general_tasks t where t.id = p_task and t.created_by = auth.uid() and app.is_manager_or_above())
  )
$$;

alter table public.general_tasks enable row level security;
alter table public.general_task_assignees enable row level security;
alter table public.general_task_comments enable row level security;

create policy "general tasks: involved read" on public.general_tasks
  for select to authenticated using (app.can_see_general_task(id) or (created_by = auth.uid() and app.is_manager_or_above()));
create policy "general tasks: managers create" on public.general_tasks
  for insert to authenticated with check (app.is_manager_or_above() and created_by = auth.uid());
create policy "general tasks: involved update" on public.general_tasks
  for update to authenticated using (app.can_see_general_task(id)) with check (app.can_see_general_task(id));
create policy "general tasks: creator or admin delete" on public.general_tasks
  for delete to authenticated using (app.can_manage_general_task(id));

create policy "general task people: involved read" on public.general_task_assignees
  for select to authenticated using (app.can_see_general_task(task_id));
create policy "general task people: creator or admin add" on public.general_task_assignees
  for insert to authenticated with check (app.can_manage_general_task(task_id));
create policy "general task people: creator or admin remove" on public.general_task_assignees
  for delete to authenticated using (app.can_manage_general_task(task_id));

create policy "general task comments: involved read" on public.general_task_comments
  for select to authenticated using (app.can_see_general_task(task_id));
create policy "general task comments: involved write" on public.general_task_comments
  for insert to authenticated with check (app.can_see_general_task(task_id) and author_id = auth.uid());
create policy "general task comments: own delete" on public.general_task_comments
  for delete to authenticated using (author_id = auth.uid() or app.is_admin());

revoke all on public.general_tasks, public.general_task_assignees, public.general_task_comments from public, anon;
grant select, insert, update, delete on public.general_tasks to authenticated;
grant select, insert, delete on public.general_task_assignees, public.general_task_comments to authenticated;
grant all on public.general_tasks, public.general_task_assignees, public.general_task_comments to service_role;

-- Assignees may only change status and checklist; done ⇄ completed_at; tell the creator.
create or replace function app.general_task_before_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if not app.is_service_role() and not app.can_manage_general_task(old.id) then
    if new.title is distinct from old.title or new.description is distinct from old.description
       or new.client_id is distinct from old.client_id or new.priority is distinct from old.priority
       or new.due_date is distinct from old.due_date or new.created_by is distinct from old.created_by then
      raise exception 'Only the person who created this task can change that' using errcode = '42501';
    end if;
  end if;
  if new.status = 'done' and old.status <> 'done' then new.completed_at := now();
  elsif new.status <> 'done' then new.completed_at := null;
  end if;
  new.updated_at := now();
  return new;
end;
$$;
create trigger general_tasks_before_update before update on public.general_tasks
  for each row execute function app.general_task_before_update();

create or replace function app.general_task_after_update()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  label text := case new.status when 'done' then 'Done' when 'working' then 'Working on it' when 'waiting' then 'Waiting' else 'Not started' end;
begin
  if new.status is distinct from old.status and new.created_by is not null then
    perform app.notify(new.created_by, 'task.status',
      app.person_name(auth.uid()) || case when new.status = 'done' then ' finished: ' else ' → ' || label || ': ' end || new.title,
      'General task', '/my-tasks?general=' || new.id, null, null, auth.uid());
  end if;
  return null;
end;
$$;
create trigger general_tasks_after_update after update of status on public.general_tasks
  for each row execute function app.general_task_after_update();

-- Someone is given the task → notification.
create or replace function app.general_task_assigned()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  t public.general_tasks%rowtype;
begin
  select * into t from public.general_tasks where id = new.task_id;
  perform app.notify(new.user_id, 'task.assigned',
    app.person_name(auth.uid()) || ' gave you a task: ' || t.title,
    coalesce((select 'Client: ' || c.name from public.clients c where c.id = t.client_id), 'General task'),
    '/my-tasks?general=' || t.id, null, null, auth.uid());
  return null;
end;
$$;
create trigger general_task_assignees_notify after insert on public.general_task_assignees
  for each row execute function app.general_task_assigned();

-- New comment → creator and assignees (not the writer).
create or replace function app.general_task_commented()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  t public.general_tasks%rowtype;
  r record;
begin
  select * into t from public.general_tasks where id = new.task_id;
  for r in
    select t.created_by as user_id where t.created_by is not null
    union
    select a.user_id from public.general_task_assignees a where a.task_id = t.id
  loop
    perform app.notify(r.user_id, 'task.comment', app.person_name(new.author_id) || ' commented on ' || t.title,
      left(new.body, 300), '/my-tasks?general=' || t.id, null, null, new.author_id);
  end loop;
  return null;
end;
$$;
create trigger general_task_comments_notify after insert on public.general_task_comments
  for each row execute function app.general_task_commented();

-- My general tasks: assigned to me, created by me, or (p_all) every one for administrators.
create or replace function public.get_general_tasks(p_all boolean default false)
returns jsonb
language sql stable security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', t.id, 'title', t.title, 'description', t.description, 'status', t.status, 'priority', t.priority,
    'due_date', t.due_date, 'checklist', t.checklist, 'completed_at', t.completed_at, 'created_at', t.created_at,
    'created_by', t.created_by, 'creator_name', app.person_name(t.created_by),
    'client', (select jsonb_build_object('id', c.id, 'name', c.name) from public.clients c where c.id = t.client_id),
    'assignees', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'first_name', p.first_name, 'last_name', p.last_name, 'email', p.email, 'avatar_url', p.avatar_url) order by p.first_name)
                           from public.general_task_assignees a join public.profiles p on p.id = a.user_id where a.task_id = t.id), '[]'::jsonb),
    'comment_count', (select count(*) from public.general_task_comments x where x.task_id = t.id)
  ) order by t.completed_at nulls first, t.due_date nulls last, t.created_at desc), '[]'::jsonb)
  from public.general_tasks t
  where app.is_active()
    and (
      t.created_by = auth.uid()
      or exists (select 1 from public.general_task_assignees a where a.task_id = t.id and a.user_id = auth.uid())
      or (p_all and app.is_admin())
    )
    and (t.completed_at is null or t.completed_at > now() - interval '30 days')
$$;
revoke all on function public.get_general_tasks(boolean) from public, anon;
grant execute on function public.get_general_tasks(boolean) to authenticated;

-- Daily job (server only): due tomorrow / today / overdue (once, the day after) for assignees.
create or replace function public.create_general_task_due_notifications()
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare
  today date := public.malta_today();
  r record;
  n integer := 0;
  kind text;
  v_title text;
begin
  for r in
    select t.id, t.title, t.due_date, a.user_id
    from public.general_tasks t
    join public.general_task_assignees a on a.task_id = t.id
    where t.completed_at is null and t.due_date between today - 1 and today + 1
  loop
    kind := case when r.due_date < today then 'task.overdue' else 'task.due_soon' end;
    v_title := case when r.due_date < today then 'Overdue: ' when r.due_date = today then 'Due today: ' else 'Due tomorrow: ' end || r.title;
    if not exists (
      select 1 from public.notifications x
      where x.user_id = r.user_id and x.type = kind and x.link = '/my-tasks?general=' || r.id and x.created_at > now() - interval '20 hours'
    ) then
      perform app.notify(r.user_id, kind, v_title, 'General task', '/my-tasks?general=' || r.id, null, null, null);
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$$;
revoke all on function public.create_general_task_due_notifications() from public, anon, authenticated;
grant execute on function public.create_general_task_due_notifications() to service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261208000027_message_repeat_window.sql
-- =====================================================================
-- Orion Projects — 0027 When important messages are sent again
--
-- Unread important messages are sent again only inside a time window.
-- Administrators set the default in Admin → Settings (07:00–17:00, every
-- day, for 3 days) and can change it for a single message when sending.
-- The first notification always goes out straight away.
-- =====================================================================

alter table public.app_settings
  add column message_repeat_from          time     not null default '07:00',
  add column message_repeat_to            time     not null default '17:00',
  add column message_repeat_weekdays_only boolean  not null default false,
  add column message_repeat_days          smallint not null default 3 check (message_repeat_days between 1 and 14),
  add constraint app_settings_message_window check (message_repeat_from < message_repeat_to);

alter table public.announcements
  add column repeat_from          time     not null default '07:00',
  add column repeat_to            time     not null default '17:00',
  add column repeat_weekdays_only boolean  not null default false,
  add column repeat_days          smallint not null default 3 check (repeat_days between 1 and 14),
  add constraint announcements_repeat_window check (repeat_from < repeat_to);

-- Sending now also takes the window (null = the default from Admin → Settings).
drop function public.send_announcement(text, text, uuid[], smallint);
create or replace function public.send_announcement(
  p_title text, p_body text, p_user_ids uuid[], p_remind_every_hours smallint default 2,
  p_repeat_from time default null, p_repeat_to time default null,
  p_weekdays_only boolean default null, p_repeat_days smallint default null
)
returns uuid
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  a_id uuid;
  r record;
  s public.app_settings%rowtype;
begin
  if not app.is_admin() then
    raise exception 'Only administrators can send important messages' using errcode = '42501';
  end if;
  select * into s from public.app_settings where id;
  insert into public.announcements (title, body, remind_every_hours, created_by, repeat_from, repeat_to, repeat_weekdays_only, repeat_days)
  values (
    trim(p_title), trim(p_body), p_remind_every_hours, auth.uid(),
    coalesce(p_repeat_from, s.message_repeat_from), coalesce(p_repeat_to, s.message_repeat_to),
    coalesce(p_weekdays_only, s.message_repeat_weekdays_only), coalesce(p_repeat_days, s.message_repeat_days)
  )
  returning id into a_id;

  for r in
    select pr.id from public.profiles pr
    where pr.id = any (p_user_ids) and pr.status = 'active'
  loop
    insert into public.announcement_recipients (announcement_id, user_id) values (a_id, r.id);
    insert into public.notifications (user_id, type, title, body, link, actor_id)
    values (r.id, 'announcement', left('Important: ' || trim(p_title), 200), left(trim(p_body), 1000), '/home?message=' || a_id, auth.uid());
  end loop;

  if not exists (select 1 from public.announcement_recipients where announcement_id = a_id) then
    raise exception 'Choose at least one active person' using errcode = '22023';
  end if;
  return a_id;
end;
$$;
revoke all on function public.send_announcement(text, text, uuid[], smallint, time, time, boolean, smallint) from public, anon;
grant execute on function public.send_announcement(text, text, uuid[], smallint, time, time, boolean, smallint) to authenticated, service_role;

-- Every 15 minutes (server only): send unread messages again inside each message's window.
create or replace function public.queue_announcement_reminders(p_now timestamptz default now())
returns integer
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  local_ts timestamp := p_now at time zone 'Europe/Malta';
  n integer := 0;
  r record;
begin
  for r in
    select rc.announcement_id, rc.user_id, a.title, a.body
    from public.announcement_recipients rc
    join public.announcements a on a.id = rc.announcement_id
    join public.profiles pr on pr.id = rc.user_id and pr.status = 'active'
    where rc.read_at is null
      and a.remind_every_hours is not null
      and a.created_at > p_now - make_interval(days => a.repeat_days)
      and local_ts::time between a.repeat_from and a.repeat_to
      and not (a.repeat_weekdays_only and extract(isodow from local_ts) in (6, 7))
      and rc.times_sent < 30
      and rc.last_sent_at <= p_now - make_interval(hours => a.remind_every_hours) + interval '2 minutes'
    for update of rc skip locked
  loop
    update public.announcement_recipients set last_sent_at = p_now, times_sent = times_sent + 1
    where announcement_id = r.announcement_id and user_id = r.user_id;
    insert into public.notifications (user_id, type, title, body, link)
    values (r.user_id, 'announcement', left('Reminder – important: ' || r.title, 200), left(r.body, 1000), '/home?message=' || r.announcement_id);
    n := n + 1;
  end loop;
  return n;
end;
$$;
revoke all on function public.queue_announcement_reminders(timestamptz) from public, anon, authenticated;
grant execute on function public.queue_announcement_reminders(timestamptz) to service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261209000028_audit_trail.sql
-- =====================================================================
-- Orion Projects — 0028 Audit trail and recycle bin
--
-- 1. audit_log: who created / changed / deleted what, and when — tasks,
--    groups, projects, people on projects, general tasks, material
--    requests, daily updates, comments and people's levels. Only
--    administrators can read it (Admin → Audit log). Names are copied in,
--    so entries still read well after things are deleted.
-- 2. deleted_tasks: a full copy of every deleted task (checklist, people,
--    comments, files, links) for 30 days, so an administrator can restore it.
-- 3. Task history (activity_log) also records people being assigned or
--    removed, "internal" being switched, and restores.
-- =====================================================================

-- Keep a task's history when it is deleted, so it is still there if the task is restored.
alter table public.activity_log drop constraint if exists activity_log_task_id_fkey;

create table public.audit_log (
  id           bigint generated always as identity primary key,
  created_at   timestamptz not null default now(),
  actor_id     uuid references public.profiles (id) on delete set null,
  actor_name   text not null default 'System',
  action       text not null,        -- created | updated | deleted | restored | added | removed | assigned | unassigned
  entity       text not null,        -- task | group | project | project_member | general_task | material_request | daily_update | comment | user
  entity_id    uuid,
  project_id   uuid,                 -- no foreign key: entries outlive the project
  project_name text,
  title        text,                 -- what it was called, e.g. the task title
  changes      jsonb not null default '{}'::jsonb   -- { field: [before, after] }, readable values
);
create index audit_log_created_idx on public.audit_log (created_at desc);
create index audit_log_project_idx on public.audit_log (project_id, created_at desc);
create index audit_log_entity_idx on public.audit_log (entity_id);
create index audit_log_actor_idx on public.audit_log (actor_id, created_at desc);

alter table public.audit_log enable row level security;
create policy "audit: admins read" on public.audit_log for select to authenticated using (app.is_admin());
revoke all on public.audit_log from public, anon, authenticated;
grant select on public.audit_log to authenticated;
grant all on public.audit_log to service_role;

create or replace function app.audit(p_action text, p_entity text, p_entity_id uuid, p_project uuid, p_title text, p_changes jsonb default '{}'::jsonb)
returns void
language sql volatile security definer
set search_path = ''
as $$
  insert into public.audit_log (actor_id, actor_name, action, entity, entity_id, project_id, project_name, title, changes)
  values (
    auth.uid(),
    coalesce(app.person_name(auth.uid()), 'System'),
    p_action, p_entity, p_entity_id, p_project,
    (select name from public.projects where id = p_project),
    left(p_title, 300),
    coalesce(p_changes, '{}'::jsonb)
  )
$$;

-- jsonb diff helper: { field: [old, new] } for the listed fields that changed.
create or replace function app.diff(o jsonb, n jsonb, fields text[])
returns jsonb
language sql immutable
set search_path = ''
as $$
  select coalesce(jsonb_object_agg(f, jsonb_build_array(o -> f, n -> f)), '{}'::jsonb)
  from unnest(fields) f
  where (o -> f) is distinct from (n -> f)
$$;

-- ---------------------------------------------------------------------
-- Tasks
-- ---------------------------------------------------------------------
create or replace function app.audit_tasks()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  o jsonb;
  n jsonb;
  d jsonb;
begin
  if tg_op = 'INSERT' then
    perform app.audit(case when current_setting('app.restoring', true) = '1' then 'restored' else 'created' end,
      'task', new.id, new.project_id, new.title);
    return null;
  elsif tg_op = 'DELETE' then
    if not exists (select 1 from public.projects where id = old.project_id) then return null; end if; -- whole project deleted
    perform app.audit('deleted', 'task', old.id, old.project_id, old.title,
      case when not exists (select 1 from public.groups where id = old.group_id) then '{"reason": "its group was deleted"}'::jsonb else '{}'::jsonb end);
    return null;
  end if;

  o := to_jsonb(old);
  n := to_jsonb(new);
  d := app.diff(o, n, array['title', 'priority', 'start_date', 'due_date', 'progress', 'is_internal']);
  if o -> 'description' is distinct from n -> 'description' then d := d || '{"description": ["…", "edited"]}'; end if;
  if old.status_id is distinct from new.status_id then
    d := d || jsonb_build_object('status', jsonb_build_array(
      (select name from public.status_labels where id = old.status_id), (select name from public.status_labels where id = new.status_id)));
  end if;
  if old.group_id is distinct from new.group_id then
    d := d || jsonb_build_object('group', jsonb_build_array(
      (select name from public.groups where id = old.group_id), (select name from public.groups where id = new.group_id)));
  end if;
  if d <> '{}'::jsonb then
    perform app.audit('updated', 'task', new.id, new.project_id, new.title, d);
  end if;
  return null;
end;
$$;
create trigger tasks_audit after insert or update or delete on public.tasks
  for each row execute function app.audit_tasks();

-- People assigned / removed (audit + the task's own history).
create or replace function app.audit_task_assignees()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  t public.tasks%rowtype;
  r public.task_assignees%rowtype := case when tg_op = 'INSERT' then new else old end;
  who text := app.person_name(r.user_id);
begin
  select * into t from public.tasks where id = r.task_id;
  if not found then return null; end if; -- the task itself is being deleted
  perform app.audit(case when tg_op = 'INSERT' then 'assigned' else 'unassigned' end, 'task', t.id, t.project_id, t.title,
    jsonb_build_object('person', who));
  insert into public.activity_log (project_id, task_id, actor_id, action, changes)
  values (t.project_id, t.id, auth.uid(), case when tg_op = 'INSERT' then 'task.assigned' else 'task.unassigned' end, jsonb_build_object('person', who));
  return null;
end;
$$;
create trigger task_assignees_audit after insert or delete on public.task_assignees
  for each row execute function app.audit_task_assignees();

-- Comments deleted.
create or replace function app.audit_comment_deleted()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  t public.tasks%rowtype;
begin
  select * into t from public.tasks where id = old.task_id;
  if not found then return null; end if;
  perform app.audit('deleted', 'comment', old.id, t.project_id, t.title,
    jsonb_build_object('comment', left(old.body, 300), 'written_by', app.person_name(old.author_id)));
  return null;
end;
$$;
create trigger comments_audit after delete on public.comments
  for each row execute function app.audit_comment_deleted();

-- ---------------------------------------------------------------------
-- Groups, projects, people on projects
-- ---------------------------------------------------------------------
create or replace function app.audit_groups()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform app.audit('created', 'group', new.id, new.project_id, new.name);
  elsif tg_op = 'DELETE' then
    if exists (select 1 from public.projects where id = old.project_id) then
      perform app.audit('deleted', 'group', old.id, old.project_id, old.name,
        jsonb_build_object('tasks_deleted', (select count(*) from public.tasks where group_id = old.id)));
    end if;
  elsif old.name is distinct from new.name then
    perform app.audit('updated', 'group', new.id, new.project_id, new.name, jsonb_build_object('name', jsonb_build_array(old.name, new.name)));
  end if;
  return null;
end;
$$;
create trigger groups_audit after insert or update or delete on public.groups
  for each row execute function app.audit_groups();

create or replace function app.audit_projects()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  d jsonb;
begin
  if tg_op = 'INSERT' then
    perform app.audit('created', 'project', new.id, new.id, new.name);
  elsif tg_op = 'DELETE' then
    insert into public.audit_log (actor_id, actor_name, action, entity, entity_id, project_id, project_name, title)
    values (auth.uid(), coalesce(app.person_name(auth.uid()), 'System'), 'deleted', 'project', old.id, old.id, old.name, old.name);
  else
    d := app.diff(to_jsonb(old), to_jsonb(new), array['name', 'status', 'start_date', 'end_date']);
    if d <> '{}'::jsonb then perform app.audit('updated', 'project', new.id, new.id, new.name, d); end if;
  end if;
  return null;
end;
$$;
create trigger projects_audit after insert or update or delete on public.projects
  for each row execute function app.audit_projects();

create or replace function app.audit_project_members()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  r public.project_members%rowtype := case when tg_op = 'INSERT' then new else old end;
begin
  if not exists (select 1 from public.projects where id = r.project_id) then return null; end if;
  perform app.audit(case when tg_op = 'INSERT' then 'added' else 'removed' end, 'project_member', r.user_id, r.project_id, app.person_name(r.user_id));
  return null;
end;
$$;
create trigger project_members_audit after insert or delete on public.project_members
  for each row execute function app.audit_project_members();

-- ---------------------------------------------------------------------
-- General tasks, material requests, daily updates, people's levels
-- ---------------------------------------------------------------------
create or replace function app.audit_general_tasks()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  d jsonb;
begin
  if tg_op = 'INSERT' then
    perform app.audit('created', 'general_task', new.id, null, new.title);
  elsif tg_op = 'DELETE' then
    perform app.audit('deleted', 'general_task', old.id, null, old.title);
  else
    d := app.diff(to_jsonb(old), to_jsonb(new), array['title', 'status', 'priority', 'due_date']);
    if d <> '{}'::jsonb then perform app.audit('updated', 'general_task', new.id, null, new.title, d); end if;
  end if;
  return null;
end;
$$;
create trigger general_tasks_audit after insert or update or delete on public.general_tasks
  for each row execute function app.audit_general_tasks();

create or replace function app.audit_material_requests()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    perform app.audit('created', 'material_request', new.id, new.project_id, 'Material request #' || new.number);
  elsif tg_op = 'DELETE' then
    if exists (select 1 from public.projects where id = old.project_id) then
      perform app.audit('deleted', 'material_request', old.id, old.project_id, 'Material request #' || old.number);
    end if;
  elsif old.status is distinct from new.status then
    perform app.audit('updated', 'material_request', new.id, new.project_id, 'Material request #' || new.number,
      jsonb_build_object('status', jsonb_build_array(old.status, new.status)));
  end if;
  return null;
end;
$$;
create trigger material_requests_audit after insert or update or delete on public.material_requests
  for each row execute function app.audit_material_requests();

create or replace function app.audit_daily_updates()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  label text := 'Daily update by ' || app.person_name(coalesce(new.author_id, old.author_id)) || ' for ' || to_char(coalesce(new.work_date, old.work_date), 'DD/MM/YYYY');
begin
  if tg_op = 'DELETE' then
    if exists (select 1 from public.projects where id = old.project_id) then
      perform app.audit('deleted', 'daily_update', old.id, old.project_id, label, jsonb_build_object('text', left(old.work_done, 300)));
    end if;
  elsif old.work_done is distinct from new.work_done or old.hours is distinct from new.hours or old.issues is distinct from new.issues then
    perform app.audit('updated', 'daily_update', new.id, new.project_id, label, app.diff(to_jsonb(old), to_jsonb(new), array['work_done', 'hours', 'issues']));
  end if;
  return null;
end;
$$;
create trigger daily_updates_audit after update or delete on public.daily_updates
  for each row execute function app.audit_daily_updates();

create or replace function app.audit_profiles()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  d jsonb := app.diff(to_jsonb(old), to_jsonb(new), array['role', 'status', 'first_name', 'last_name']);
begin
  if d <> '{}'::jsonb then
    perform app.audit('updated', 'user', new.id, null, coalesce(nullif(trim(new.first_name || ' ' || new.last_name), ''), new.email::text), d);
  end if;
  return null;
end;
$$;
create trigger profiles_audit after update on public.profiles
  for each row execute function app.audit_profiles();

-- ---------------------------------------------------------------------
-- Recycle bin for deleted tasks (30 days)
-- ---------------------------------------------------------------------
create table public.deleted_tasks (
  task_id         uuid primary key,
  project_id      uuid not null,
  project_name    text,
  title           text not null,
  deleted_at      timestamptz not null default now(),
  deleted_by      uuid references public.profiles (id) on delete set null,
  deleted_by_name text,
  snapshot        jsonb not null,
  restored_at     timestamptz,
  restored_by     uuid references public.profiles (id) on delete set null
);
create index deleted_tasks_deleted_idx on public.deleted_tasks (deleted_at desc);
alter table public.deleted_tasks enable row level security;
create policy "recycle bin: admins read" on public.deleted_tasks for select to authenticated using (app.is_admin());
revoke all on public.deleted_tasks from public, anon, authenticated;
grant select on public.deleted_tasks to authenticated;
grant all on public.deleted_tasks to service_role;

-- Before a task goes, keep a full copy — also when its group is deleted (restoring then puts
-- it in the first group). Not when the whole project is deleted.
create or replace function app.keep_deleted_task()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.projects where id = old.project_id) then return old; end if;
  insert into public.deleted_tasks (task_id, project_id, project_name, title, deleted_by, deleted_by_name, snapshot)
  values (
    old.id, old.project_id, (select name from public.projects where id = old.project_id), old.title,
    auth.uid(), coalesce(app.person_name(auth.uid()), 'System'),
    jsonb_build_object(
      'task', to_jsonb(old),
      'group_name', (select name from public.groups where id = old.group_id),
      'assignees', coalesce((select jsonb_agg(to_jsonb(a)) from public.task_assignees a where a.task_id = old.id), '[]'),
      'checklist', coalesce((select jsonb_agg(to_jsonb(c)) from public.task_checklist_items c where c.task_id = old.id), '[]'),
      'comments', coalesce((select jsonb_agg(to_jsonb(c)) from public.comments c where c.task_id = old.id), '[]'),
      'attachments', coalesce((select jsonb_agg(to_jsonb(f)) from public.attachments f where f.task_id = old.id), '[]'),
      'blocked_by', coalesce((select jsonb_agg(d.depends_on_task_id) from public.task_dependencies d where d.task_id = old.id), '[]'),
      'blocking', coalesce((select jsonb_agg(d.task_id) from public.task_dependencies d where d.depends_on_task_id = old.id), '[]')
    )
  )
  on conflict (task_id) do update set
    deleted_at = now(), deleted_by = excluded.deleted_by, deleted_by_name = excluded.deleted_by_name,
    snapshot = excluded.snapshot, title = excluded.title, restored_at = null, restored_by = null;
  return old;
end;
$$;
create trigger tasks_keep_deleted before delete on public.tasks
  for each row execute function app.keep_deleted_task();

-- Administrators: put a deleted task back where it was (or in the first group if that one is gone).
create or replace function public.restore_task(p_task uuid)
returns uuid
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  d public.deleted_tasks%rowtype;
  t jsonb;
  g uuid;
begin
  if not app.is_admin() then
    raise exception 'Only administrators can restore deleted tasks' using errcode = '42501';
  end if;
  select * into d from public.deleted_tasks where task_id = p_task and restored_at is null for update;
  if not found then raise exception 'This task is not in the recycle bin' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.projects where id = d.project_id) then
    raise exception 'Its project has been deleted, so the task can''t be put back' using errcode = '22023';
  end if;
  if exists (select 1 from public.tasks where id = p_task) then
    raise exception 'This task already exists' using errcode = '23505';
  end if;

  t := d.snapshot -> 'task';
  g := (t ->> 'group_id')::uuid;
  if not exists (select 1 from public.groups where id = g) then
    select id into g from public.groups where project_id = d.project_id order by position limit 1;
    if g is null then raise exception 'The project has no groups to put it in' using errcode = '22023'; end if;
  end if;
  t := t || jsonb_build_object('group_id', g);
  if not exists (select 1 from public.status_labels where id = (t ->> 'status_id')::uuid) then
    t := t || '{"status_id": null}';
  end if;
  if (t ->> 'repeated_from') is not null and not exists (select 1 from public.tasks where id = (t ->> 'repeated_from')::uuid) then
    t := t || '{"repeated_from": null}';
  end if;

  perform set_config('app.restoring', '1', true);
  insert into public.tasks select * from jsonb_populate_record(null::public.tasks, t);
  insert into public.task_checklist_items select * from jsonb_populate_recordset(null::public.task_checklist_items, d.snapshot -> 'checklist');
  insert into public.attachments select * from jsonb_populate_recordset(null::public.attachments, d.snapshot -> 'attachments');
  insert into public.comments
    select * from jsonb_populate_recordset(null::public.comments, d.snapshot -> 'comments') c
    where exists (select 1 from public.profiles p where p.id = c.author_id);
  insert into public.task_assignees
    select * from jsonb_populate_recordset(null::public.task_assignees, d.snapshot -> 'assignees') a
    where exists (select 1 from public.profiles p where p.id = a.user_id and p.status = 'active');
  insert into public.task_dependencies (task_id, depends_on_task_id)
    select p_task, x::uuid from jsonb_array_elements_text(d.snapshot -> 'blocked_by') x
    where exists (select 1 from public.tasks o where o.id = x::uuid);
  insert into public.task_dependencies (task_id, depends_on_task_id)
    select x::uuid, p_task from jsonb_array_elements_text(d.snapshot -> 'blocking') x
    where exists (select 1 from public.tasks o where o.id = x::uuid)
    on conflict do nothing;
  perform set_config('app.restoring', '', true);

  insert into public.activity_log (project_id, task_id, actor_id, action, changes)
  values (d.project_id, p_task, auth.uid(), 'task.restored', '{}');
  update public.deleted_tasks set restored_at = now(), restored_by = auth.uid() where task_id = p_task;
  return p_task;
end;
$$;
revoke all on function public.restore_task(uuid) from public, anon;
grant execute on function public.restore_task(uuid) to authenticated, service_role;

-- Daily job: the recycle bin keeps 30 days; the audit log keeps 2 years.
create or replace function public.cleanup_audit()
returns void
language sql volatile security definer
set search_path = ''
as $$
  delete from public.deleted_tasks where deleted_at < now() - interval '30 days';
  delete from public.audit_log where created_at < now() - interval '2 years';
$$;
revoke all on function public.cleanup_audit() from public, anon, authenticated;
grant execute on function public.cleanup_audit() to service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261210000029_material_documents.sql
-- =====================================================================
-- Orion Projects — 0029 Delivery documents and "received on site"
--
-- 1. Anyone on the project can attach the delivery note, invoice or another
--    document (photo or file) to a material request. Managers are told.
-- 2. The person receiving on site (technicians too) can mark a request as
--    received, with the quantities that came — Delivered, or Partly
--    delivered if something is short. Managers are told and can correct it.
-- Files live in project-files/<project_id>/materials/<request_id>/docs/…
-- =====================================================================

create table public.material_request_documents (
  id           uuid primary key,
  request_id   uuid not null references public.material_requests (id) on delete cascade,
  project_id   uuid not null references public.projects (id) on delete cascade,
  kind         text not null default 'delivery_note' check (kind in ('delivery_note', 'invoice', 'other')),
  storage_path text not null unique,
  file_name    text not null check (char_length(file_name) between 1 and 255),
  mime_type    text,
  size_bytes   bigint check (size_bytes >= 0),
  uploaded_by  uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at   timestamptz not null default now()
);
create index material_documents_request_idx on public.material_request_documents (request_id, created_at);

alter table public.material_request_documents enable row level security;
create policy "material documents: read" on public.material_request_documents
  for select to authenticated using (app.can_view_project(project_id));
create policy "material documents: add" on public.material_request_documents
  for insert to authenticated with check (
    uploaded_by = auth.uid() and project_id = app.material_project(request_id) and app.can_edit_project(project_id)
  );
create policy "material documents: uploader or manager delete" on public.material_request_documents
  for delete to authenticated using (uploaded_by = auth.uid() or app.can_manage_project(project_id));
revoke all on public.material_request_documents from public, anon;
grant select, insert, delete on public.material_request_documents to authenticated;
grant all on public.material_request_documents to service_role;

alter table public.material_requests
  add column received_by uuid references public.profiles (id) on delete set null,
  add column received_at timestamptz;

-- The project's managers (or, if it has none, the administrators).
create or replace function app.material_handlers(p_project uuid)
returns setof uuid
language sql stable security definer
set search_path = ''
as $$
  select m.user_id from public.project_members m join public.profiles pr on pr.id = m.user_id
  where m.project_id = p_project and pr.role in ('admin', 'manager') and pr.status = 'active'
  union
  select pr.id from public.profiles pr
  where pr.role = 'admin' and pr.status = 'active'
    and not exists (select 1 from public.project_members m join public.profiles x on x.id = m.user_id
                    where m.project_id = p_project and x.role in ('admin', 'manager'))
$$;

-- A document was added: note it in the request's history and tell the managers.
create or replace function app.material_document_added()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  r public.material_requests%rowtype;
  label text := case new.kind when 'delivery_note' then 'a delivery note' when 'invoice' then 'an invoice' else 'a document' end;
  u uuid;
begin
  select * into r from public.material_requests where id = new.request_id;
  insert into public.material_request_events (request_id, actor_id, kind, detail) values (r.id, new.uploaded_by, 'document', label);
  for u in select app.material_handlers(r.project_id) union select r.requested_by loop
    perform app.notify(u, 'material.status',
      app.person_name(new.uploaded_by) || ' added ' || label || ' to material request #' || r.number || ' · ' || (select name from public.projects where id = r.project_id),
      new.file_name, '/projects/' || r.project_id || '/materials?request=' || r.id, r.project_id, null, new.uploaded_by);
  end loop;
  return null;
end;
$$;
create trigger material_documents_added after insert on public.material_request_documents
  for each row execute function app.material_document_added();

-- Received on site: anyone who can work on the project. p_deliveries = [{ item_id, delivered_qty }]
-- (items not listed keep what was already recorded). Delivered if everything has come.
create or replace function public.receive_material_request(p_id uuid, p_deliveries jsonb, p_note text default null)
returns text
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  r public.material_requests%rowtype;
  d record;
  all_in boolean;
  next_status text;
  u uuid;
begin
  select * into r from public.material_requests where id = p_id for update;
  if not found or not app.can_edit_project(r.project_id) then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  if r.status not in ('requested', 'ordered', 'partly_delivered') then
    raise exception 'This request is already closed' using errcode = '22023';
  end if;
  if jsonb_typeof(p_deliveries) <> 'array' then
    raise exception 'Say how much arrived' using errcode = '22023';
  end if;

  for d in
    select (x ->> 'item_id')::uuid as item_id, greatest(0, (x ->> 'delivered_qty')::numeric) as qty
    from jsonb_array_elements(p_deliveries) x
  loop
    update public.material_request_items set delivered_qty = d.qty where id = d.item_id and request_id = p_id;
  end loop;

  select bool_and(delivered_qty >= quantity) into all_in from public.material_request_items where request_id = p_id;
  next_status := case when coalesce(all_in, false) then 'delivered' else 'partly_delivered' end;
  update public.material_requests
     set status = next_status, received_by = auth.uid(), received_at = now()
   where id = p_id;

  if nullif(trim(coalesce(p_note, '')), '') is not null then
    insert into public.material_request_comments (request_id, author_id, body) values (p_id, auth.uid(), left(trim(p_note), 4000));
  end if;

  -- Managers hear it arrived (the requester is told by the usual status message).
  for u in select app.material_handlers(r.project_id) loop
    perform app.notify(u, 'material.status',
      'Received on site: material request #' || r.number || ' · ' || (select name from public.projects where id = r.project_id),
      app.person_name(auth.uid()) || case when next_status = 'delivered' then ' received everything.' else ' received part of it — some items are short.' end,
      '/projects/' || r.project_id || '/materials?request=' || r.id, r.project_id, null, auth.uid());
  end loop;
  return next_status;
end;
$$;
revoke all on function public.receive_material_request(uuid, jsonb, text) from public, anon;
grant execute on function public.receive_material_request(uuid, jsonb, text) to authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261211000030_variations.sql
-- =====================================================================
-- Orion Projects — 0030 Variations (VO-001, VO-002 …)
--
-- When the client changes work that's already done, the original task
-- stays Done and a new, linked task is created: "VO-001 · <title>" in the
-- project's "Variations" group, with what changed, who asked and when, and
-- the client's approval (Awaiting / Approved / Rejected). A variation can
-- also be created on its own (a brand-new extra). No amounts are kept here.
-- Managers create and edit variation details; everyone on the project can
-- work on the task as usual.
-- =====================================================================

alter table public.tasks
  add column variation_no           integer,
  add column variation_of           uuid references public.tasks (id) on delete set null,
  add column variation_reason       text check (char_length(variation_reason) <= 4000),
  add column variation_requested_by text check (char_length(variation_requested_by) <= 160),
  add column variation_requested_on date,
  add column variation_approval     text check (variation_approval in ('pending', 'approved', 'rejected'));
create unique index tasks_variation_no_idx on public.tasks (project_id, variation_no) where variation_no is not null;
create index tasks_variation_of_idx on public.tasks (variation_of) where variation_of is not null;

-- Only the project's managers (and administrators) change variation details.
-- Runs as the caller, so app.is_service_role() tells the server/functions apart from people.
create or replace function app.guard_variation_fields()
returns trigger
language plpgsql security invoker
set search_path = ''
as $$
begin
  if app.is_service_role() or app.can_manage_project(new.project_id) then return new; end if;
  if tg_op = 'INSERT' then
    if new.variation_no is not null or new.variation_of is not null or new.variation_reason is not null
       or new.variation_requested_by is not null or new.variation_requested_on is not null or new.variation_approval is not null then
      raise exception 'Only managers can create variations' using errcode = '42501';
    end if;
  elsif new.variation_no is distinct from old.variation_no or new.variation_of is distinct from old.variation_of
     or new.variation_reason is distinct from old.variation_reason or new.variation_requested_by is distinct from old.variation_requested_by
     or new.variation_requested_on is distinct from old.variation_requested_on or new.variation_approval is distinct from old.variation_approval then
    raise exception 'Only managers can change variation details' using errcode = '42501';
  end if;
  return new;
end;
$$;
create trigger tasks_guard_variation before insert or update on public.tasks
  for each row execute function app.guard_variation_fields();

-- Managers: create VO-00n — from a task (usually a completed one) or on its own.
-- Returns the new task's id. The original task is not changed.
create or replace function public.create_variation(
  p_project uuid, p_source uuid, p_title text, p_reason text,
  p_requested_by text default null, p_requested_on date default null
)
returns uuid
language plpgsql volatile security definer
set search_path = ''
as $$
declare
  src public.tasks%rowtype;
  grp uuid;
  no integer;
  first_status uuid;
  new_id uuid;
  base text;
begin
  if not app.can_manage_project(p_project) then
    raise exception 'Only managers can create variations' using errcode = '42501';
  end if;
  if p_source is not null then
    select * into src from public.tasks where id = p_source and project_id = p_project;
    if not found then raise exception 'Task not found' using errcode = 'P0002'; end if;
  end if;
  base := nullif(trim(coalesce(p_title, '')), '');
  if base is null and p_source is not null then base := regexp_replace(src.title, '^VO-\d+ · ', ''); end if;
  if base is null then raise exception 'Give the variation a name' using errcode = '22023'; end if;

  -- The project's "Variations" group (made the first time, at the end of the board).
  select g.id into grp from public.groups g where g.project_id = p_project and lower(g.name) = 'variations' order by g.position limit 1;
  if grp is null then
    insert into public.groups (project_id, name, color, position)
    values (p_project, 'Variations', '#d97706', coalesce((select max(position) from public.groups where project_id = p_project), 0) + 1)
    returning id into grp;
  end if;

  perform pg_advisory_xact_lock(hashtext('variation:' || p_project));
  select coalesce(max(variation_no), 0) + 1 into no from public.tasks where project_id = p_project;
  select s.id into first_status from public.status_labels s where s.project_id = p_project and not s.is_done order by s.position limit 1;

  insert into public.tasks (project_id, group_id, title, description, status_id, priority, position, created_by,
                            variation_no, variation_of, variation_reason, variation_requested_by, variation_requested_on, variation_approval)
  values (p_project, grp, left('VO-' || lpad(no::text, 3, '0') || ' · ' || base, 300), nullif(trim(coalesce(p_reason, '')), ''),
          first_status, coalesce(src.priority, 'medium'),
          coalesce((select max(t.position) from public.tasks t where t.group_id = grp), 0) + 1, auth.uid(),
          no, p_source, nullif(trim(coalesce(p_reason, '')), ''), nullif(trim(coalesce(p_requested_by, '')), ''),
          coalesce(p_requested_on, public.malta_today()), 'pending')
  returning id into new_id;

  -- Same people as the original (if any).
  if p_source is not null then
    insert into public.task_assignees (task_id, user_id, assigned_by)
    select new_id, a.user_id, auth.uid() from public.task_assignees a where a.task_id = p_source;
    insert into public.activity_log (project_id, task_id, actor_id, action, changes)
    values (p_project, p_source, auth.uid(), 'task.variation', jsonb_build_object('variation', 'VO-' || lpad(no::text, 3, '0')));
  end if;
  return new_id;
end;
$$;
revoke all on function public.create_variation(uuid, uuid, text, text, text, date) from public, anon;
grant execute on function public.create_variation(uuid, uuid, text, text, text, date) to authenticated, service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261212000031_daily_summary_for_all.sql
-- =====================================================================
-- Orion Projects — 0031 Daily email summary on for everyone
--
-- The morning email (tasks due soon + what happened since yesterday) was
-- opt-in. It's now on for everyone, including people who join later.
-- Anyone can still switch it off in Profile → Notifications.
-- =====================================================================

alter table public.notification_preferences alter column email_digest set default true;
update public.notification_preferences set email_digest = true where not email_digest;

-- Everyone active gets it unless they switched it off (no saved settings = on).
create or replace function public.get_digest_recipients()
returns jsonb
language sql stable security definer
set search_path = ''
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'user_id', pr.id, 'email', pr.email, 'first_name', pr.first_name,
    'notifications', coalesce((
      select jsonb_agg(jsonb_build_object('title', n.title, 'body', n.body, 'link', n.link, 'created_at', n.created_at) order by n.created_at desc)
      from (select * from public.notifications n where n.user_id = pr.id and n.read_at is null and n.created_at > now() - interval '24 hours'
            order by n.created_at desc limit 30) n
    ), '[]'),
    'tasks', coalesce((
      select jsonb_agg(jsonb_build_object('title', t.title, 'due_date', t.due_date, 'project', p.name,
                                          'link', '/projects/' || t.project_id || '/board?task=' || t.id) order by t.due_date)
      from public.tasks t join public.task_assignees a on a.task_id = t.id and a.user_id = pr.id
      join public.projects p on p.id = t.project_id
      where t.completed_at is null and p.status = 'active' and t.due_date <= public.malta_today() + 1
    ), '[]')
  )), '[]')
  from public.profiles pr
  left join public.notification_preferences np on np.user_id = pr.id
  where pr.status = 'active' and pr.email is not null and coalesce(np.email_digest, true)
$$;
revoke all on function public.get_digest_recipients() from public, anon, authenticated;
grant execute on function public.get_digest_recipients() to service_role;


-- >>>>>>>>>>>>>>>>>>>> 20261213000032_banner_messages.sql
-- =====================================================================
-- Orion Projects — 0032 Banner across the top of the app
--
-- Administrators post short announcements or reminders that show in a
-- strip at the top of every screen, one after another (every 7 seconds).
-- Each has a tone (Info / Reminder / Urgent), an optional link, who sees
-- it (everyone, some levels, people on some projects, or chosen people)
-- and how long it shows (from … until …, or until removed). It can be
-- paused. People can't close it (for now).
-- =====================================================================

create table public.banner_messages (
  id                uuid primary key default gen_random_uuid(),
  body              text not null check (char_length(trim(body)) between 1 and 200),
  link              text check (link is null or (char_length(link) <= 500 and (link like '/%' or link ~* '^https?://'))),
  tone              text not null default 'info' check (tone in ('info', 'reminder', 'urgent')),
  starts_at         timestamptz not null default now(),
  ends_at           timestamptz,
  paused            boolean not null default false,
  audience_type     text not null default 'everyone' check (audience_type in ('everyone', 'levels', 'projects', 'people')),
  audience_roles    public.app_role[] not null default '{}',
  audience_projects uuid[] not null default '{}',
  audience_people   uuid[] not null default '{}',
  position          integer not null default 0,
  created_by        uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  check (ends_at is null or ends_at > starts_at)
);
create index banner_messages_live_idx on public.banner_messages (position) where not paused;
create trigger banner_messages_touch before update on public.banner_messages
  for each row execute function app.touch_updated_at();

-- Is this banner meant for the signed-in person right now?
create or replace function app.banner_for_me(b public.banner_messages)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select app.is_active()
     and not b.paused and b.starts_at <= now() and (b.ends_at is null or b.ends_at > now())
     and case b.audience_type
           when 'everyone' then true
           when 'levels'   then app.current_role() = any (b.audience_roles)
           when 'projects' then exists (select 1 from public.project_members m where m.user_id = auth.uid() and m.project_id = any (b.audience_projects))
           when 'people'   then auth.uid() = any (b.audience_people)
           else false
         end
$$;

alter table public.banner_messages enable row level security;
create policy "banner: admins read all" on public.banner_messages
  for select to authenticated using (app.is_admin());
create policy "banner: people read what's meant for them" on public.banner_messages
  for select to authenticated using (app.banner_for_me(banner_messages));
create policy "banner: admins add" on public.banner_messages
  for insert to authenticated with check (app.is_admin() and created_by = auth.uid());
create policy "banner: admins edit" on public.banner_messages
  for update to authenticated using (app.is_admin()) with check (app.is_admin());
create policy "banner: admins delete" on public.banner_messages
  for delete to authenticated using (app.is_admin());
revoke all on public.banner_messages from public, anon;
grant select, insert, update, delete on public.banner_messages to authenticated;
grant all on public.banner_messages to service_role;

-- Audit log: who added, changed or removed a banner message.
create or replace function app.audit_banner_messages()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  d jsonb;
begin
  if tg_op = 'INSERT' then
    perform app.audit('created', 'banner', new.id, null, new.body);
  elsif tg_op = 'DELETE' then
    perform app.audit('deleted', 'banner', old.id, null, old.body);
  else
    d := app.diff(to_jsonb(old), to_jsonb(new), array['body', 'tone', 'link', 'starts_at', 'ends_at', 'paused', 'audience_type']);
    if d <> '{}'::jsonb then perform app.audit('updated', 'banner', new.id, null, new.body, d); end if;
  end if;
  return null;
end;
$$;
create trigger banner_messages_audit after insert or update or delete on public.banner_messages
  for each row execute function app.audit_banner_messages();

-- The banner messages showing for me now, in order (administrators too only see their own).
create or replace function public.my_banner_messages()
returns setof public.banner_messages
language sql stable security invoker
set search_path = ''
as $$
  select b.* from public.banner_messages b where app.banner_for_me(b) order by b.position, b.created_at
$$;
revoke all on function public.my_banner_messages() from public, anon;
grant execute on function public.my_banner_messages() to authenticated;


-- >>>>>>>>>>>>>>>>>>>> 20261214000033_aftersales.sql
-- =====================================================================
-- Orion Projects — 0033 Modules + Aftersales (stage 1)
--
-- 1. Modules: parts of the app that only chosen people can use. An
--    administrator gives each person "Agent" or "Manager" access per module
--    (administrators always have it). The first module is Aftersales.
-- 2. Aftersales: customers (with contacts and sites/installations, which
--    don't need to exist elsewhere in the app), tickets TKT-1001 …, the
--    conversation on each ticket (customer messages, replies, internal
--    notes and an automatic history), and files.
--    Emails from support@ (stage 2), response targets (stage 3) and the
--    client portal (stage 4) build on these tables.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Modules
-- ---------------------------------------------------------------------
create table public.module_access (
  user_id    uuid not null references public.profiles (id) on delete cascade,
  module     text not null check (module in ('aftersales')),
  level      text not null check (level in ('agent', 'manager')),
  granted_by uuid references public.profiles (id) on delete set null default auth.uid(),
  granted_at timestamptz not null default now(),
  primary key (user_id, module)
);

-- 'manager', 'agent' or null (no access). Administrators are always managers.
create or replace function app.module_level(p_module text)
returns text
language sql stable security definer
set search_path = ''
as $$
  select case
    when app.is_admin() then 'manager'
    when not app.is_active() then null
    else (select a.level from public.module_access a where a.user_id = auth.uid() and a.module = p_module)
  end
$$;
create or replace function app.has_module(p_module text)
returns boolean
language sql stable
set search_path = ''
as $$ select app.module_level(p_module) is not null $$;
create or replace function app.is_module_manager(p_module text)
returns boolean
language sql stable
set search_path = ''
as $$ select app.module_level(p_module) = 'manager' $$;

-- Everyone active who can use a module (optionally managers only).
create or replace function app.module_people(p_module text, p_managers_only boolean default false)
returns setof uuid
language sql stable security definer
set search_path = ''
as $$
  select pr.id from public.profiles pr where pr.status = 'active' and pr.role = 'admin'
  union
  select a.user_id from public.module_access a join public.profiles pr on pr.id = a.user_id
  where a.module = p_module and pr.status = 'active' and (not p_managers_only or a.level = 'manager')
$$;

-- People who use a module, for "assign to" lists (only for people who use it themselves).
create or replace function public.module_members(p_module text)
returns table (user_id uuid, first_name text, last_name text, email text, level text)
language sql stable security definer
set search_path = ''
as $$
  select pr.id, pr.first_name, pr.last_name, pr.email::text, case when pr.role = 'admin' then 'manager' else a.level end
  from public.profiles pr
  left join public.module_access a on a.user_id = pr.id and a.module = p_module
  where app.has_module(p_module) and pr.status = 'active' and (pr.role = 'admin' or a.level is not null)
  order by pr.first_name, pr.last_name
$$;
revoke all on function public.module_members(text) from public, anon;
grant execute on function public.module_members(text) to authenticated;

alter table public.module_access enable row level security;
create policy "module access: own or admins read" on public.module_access
  for select to authenticated using (user_id = auth.uid() or app.is_admin());
create policy "module access: admins add" on public.module_access
  for insert to authenticated with check (app.is_admin());
create policy "module access: admins change" on public.module_access
  for update to authenticated using (app.is_admin()) with check (app.is_admin());
create policy "module access: admins remove" on public.module_access
  for delete to authenticated using (app.is_admin());
revoke all on public.module_access from public, anon;
grant select, insert, update, delete on public.module_access to authenticated;
grant all on public.module_access to service_role;

-- ---------------------------------------------------------------------
-- Aftersales: customers, contacts, sites, categories
-- ---------------------------------------------------------------------
create table public.as_customers (
  id         uuid primary key default gen_random_uuid(),
  name       text not null check (char_length(trim(name)) between 1 and 160),
  kind       text not null default 'company' check (kind in ('company', 'person')),
  phone      text check (char_length(phone) <= 40),
  address    text check (char_length(address) <= 300),
  notes      text check (char_length(notes) <= 4000),
  client_id  uuid references public.clients (id) on delete set null, -- optional link to Clients in the app
  created_by uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index as_customers_name_idx on public.as_customers (lower(name));
create trigger as_customers_touch before update on public.as_customers
  for each row execute function app.touch_updated_at();

create table public.as_contacts (
  id          uuid primary key default gen_random_uuid(),
  customer_id uuid not null references public.as_customers (id) on delete cascade,
  name        text not null default '' check (char_length(name) <= 160),
  email       extensions.citext unique check (email is null or (char_length(email) <= 254 and email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$')),
  phone       text check (char_length(phone) <= 40),
  created_at  timestamptz not null default now()
);
create index as_contacts_customer_idx on public.as_contacts (customer_id);

create table public.as_sites (
  id            uuid primary key default gen_random_uuid(),
  customer_id   uuid not null references public.as_customers (id) on delete cascade,
  name          text not null check (char_length(trim(name)) between 1 and 160),
  address       text check (char_length(address) <= 300),
  handover_date date,
  warranty_end  date,
  project_id    uuid references public.projects (id) on delete set null, -- optional link to a project in the app
  notes         text check (char_length(notes) <= 4000),
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index as_sites_customer_idx on public.as_sites (customer_id);
create trigger as_sites_touch before update on public.as_sites
  for each row execute function app.touch_updated_at();

create table public.as_categories (
  id       uuid primary key default gen_random_uuid(),
  name     text not null unique check (char_length(trim(name)) between 1 and 60),
  position integer not null default 0,
  active   boolean not null default true
);
insert into public.as_categories (name, position) values
  ('Fire Alarm', 1), ('CCTV', 2), ('Access Control', 3), ('Sound System', 4), ('Intercom', 5),
  ('Plumbing', 6), ('Electrical', 7), ('Air Conditioning', 8), ('Ventilation', 9), ('Automation', 10);

-- ---------------------------------------------------------------------
-- Tickets, conversation and files
-- ---------------------------------------------------------------------
create sequence public.as_ticket_number_seq start 1001;

create table public.as_tickets (
  id                uuid primary key default gen_random_uuid(),
  number            integer not null unique default nextval('public.as_ticket_number_seq'),
  subject           text not null check (char_length(trim(subject)) between 1 and 300),
  status            text not null default 'new' check (status in ('new', 'assigned', 'in_progress', 'waiting', 'resolved', 'closed')),
  priority          text not null default 'normal' check (priority in ('low', 'normal', 'high', 'urgent')),
  category_id       uuid references public.as_categories (id) on delete set null,
  customer_id       uuid references public.as_customers (id) on delete set null,
  contact_id        uuid references public.as_contacts (id) on delete set null,
  site_id           uuid references public.as_sites (id) on delete set null,
  assigned_to       uuid references public.profiles (id) on delete set null,
  source            text not null default 'staff' check (source in ('email', 'portal', 'staff')),
  created_by        uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  first_response_at timestamptz,
  last_customer_at  timestamptz,
  last_staff_at     timestamptz,
  resolved_at       timestamptz,
  closed_at         timestamptz
);
alter sequence public.as_ticket_number_seq owned by public.as_tickets.number;
create index as_tickets_status_idx on public.as_tickets (status, created_at desc);
create index as_tickets_customer_idx on public.as_tickets (customer_id);
create index as_tickets_assigned_idx on public.as_tickets (assigned_to) where status not in ('resolved', 'closed');

create table public.as_messages (
  id               uuid primary key default gen_random_uuid(),
  ticket_id        uuid not null references public.as_tickets (id) on delete cascade,
  -- customer: from the customer (email, portal, or logged by staff, e.g. a phone call)
  -- reply: our answer to the customer · note: internal, never shown to the customer
  -- event: history written by the app (status, assignment…)
  kind             text not null check (kind in ('customer', 'reply', 'note', 'event')),
  author_id        uuid references public.profiles (id) on delete set null default auth.uid(),
  from_name        text check (char_length(from_name) <= 160),
  from_email       extensions.citext check (char_length(from_email) <= 254),
  body             text not null check (char_length(body) between 1 and 100000),
  email_message_id text check (char_length(email_message_id) <= 1000), -- stage 2
  email_status     text check (email_status in ('pending', 'sent', 'failed')), -- stage 2
  created_at       timestamptz not null default now()
);
create index as_messages_ticket_idx on public.as_messages (ticket_id, created_at);

create table public.as_files (
  id           uuid primary key,
  ticket_id    uuid not null references public.as_tickets (id) on delete cascade,
  message_id   uuid references public.as_messages (id) on delete set null,
  storage_path text not null unique,
  file_name    text not null check (char_length(file_name) between 1 and 255),
  mime_type    text,
  size_bytes   bigint check (size_bytes >= 0),
  uploaded_by  uuid references public.profiles (id) on delete set null default auth.uid(),
  created_at   timestamptz not null default now()
);
create index as_files_ticket_idx on public.as_files (ticket_id, created_at);

-- ---------------------------------------------------------------------
-- Ticket rules: status follows assignment, timestamps, history, alerts
-- ---------------------------------------------------------------------
create or replace function app.as_ticket_before()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  -- Tickets can only be given to people who use Aftersales.
  if new.assigned_to is not null and (tg_op = 'INSERT' or new.assigned_to is distinct from old.assigned_to)
     and not exists (select 1 from app.module_people('aftersales') x where x = new.assigned_to) then
    raise exception 'That person can''t use Aftersales — give them access in Admin → Modules first' using errcode = '22023';
  end if;
  -- Giving a new ticket to someone makes it Assigned; taking it away puts it back to New.
  if new.assigned_to is not null and new.status = 'new' then new.status := 'assigned'; end if;
  if new.assigned_to is null and new.status = 'assigned' then new.status := 'new'; end if;
  if new.status = 'resolved' and (tg_op = 'INSERT' or old.status <> 'resolved') then new.resolved_at := now(); end if;
  if new.status = 'closed' and (tg_op = 'INSERT' or old.status <> 'closed') then new.closed_at := now(); end if;
  if new.status not in ('resolved', 'closed') then new.resolved_at := null; new.closed_at := null; end if;
  if new.status = 'resolved' then new.closed_at := null; end if;
  if tg_op = 'UPDATE' then new.updated_at := now(); end if;
  return new;
end;
$$;
create trigger as_tickets_before before insert or update on public.as_tickets
  for each row execute function app.as_ticket_before();

create or replace function app.as_status_label(s text)
returns text
language sql immutable
set search_path = ''
as $$
  select case s when 'new' then 'New' when 'assigned' then 'Assigned' when 'in_progress' then 'In progress'
    when 'waiting' then 'Waiting for customer' when 'resolved' then 'Resolved' when 'closed' then 'Closed' else s end
$$;

create or replace function app.as_ticket_after()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  ref text := 'TKT-' || new.number;
  link text := '/aftersales/tickets/' || new.number;
  u uuid;
  d jsonb;
begin
  if tg_op = 'INSERT' then
    perform app.audit('created', 'ticket', new.id, null, ref || ' · ' || new.subject);
    insert into public.as_messages (ticket_id, kind, author_id, body)
    values (new.id, 'event', auth.uid(), 'Ticket opened' || case new.source when 'email' then ' from an email' when 'portal' then ' from the portal' else '' end);
    if new.assigned_to is not null then
      if new.assigned_to is distinct from auth.uid() then
        perform app.notify(new.assigned_to, 'ticket.assigned', ref || ' was given to you', new.subject, link);
      end if;
    else
      -- Nobody has it yet: tell the module's managers.
      for u in select app.module_people('aftersales', true) loop
        if u is distinct from auth.uid() then
          perform app.notify(u, 'ticket.new', 'New ticket ' || ref, new.subject, link);
        end if;
      end loop;
    end if;
    return null;
  end if;

  if new.status is distinct from old.status then
    insert into public.as_messages (ticket_id, kind, author_id, body)
    values (new.id, 'event', auth.uid(), 'Status: ' || app.as_status_label(old.status) || ' → ' || app.as_status_label(new.status));
  end if;
  if new.assigned_to is distinct from old.assigned_to then
    insert into public.as_messages (ticket_id, kind, author_id, body)
    values (new.id, 'event', auth.uid(), case when new.assigned_to is null then 'No longer assigned' else 'Assigned to ' || app.person_name(new.assigned_to) end);
    if new.assigned_to is not null and new.assigned_to is distinct from auth.uid() then
      perform app.notify(new.assigned_to, 'ticket.assigned', ref || ' was given to you', new.subject, link);
    end if;
  end if;
  if new.priority is distinct from old.priority then
    insert into public.as_messages (ticket_id, kind, author_id, body)
    values (new.id, 'event', auth.uid(), 'Priority: ' || initcap(old.priority) || ' → ' || initcap(new.priority));
  end if;
  d := app.diff(to_jsonb(old), to_jsonb(new), array['subject', 'status', 'priority', 'assigned_to', 'category_id', 'customer_id', 'site_id']);
  if d <> '{}'::jsonb then
    if d ? 'assigned_to' then
      d := d || jsonb_build_object('assigned_to', jsonb_build_array(app.person_name(old.assigned_to), app.person_name(new.assigned_to)));
    end if;
    perform app.audit('updated', 'ticket', new.id, null, ref || ' · ' || new.subject, d - 'category_id' - 'customer_id' - 'site_id');
  end if;
  return null;
end;
$$;
create trigger as_tickets_after after insert or update on public.as_tickets
  for each row execute function app.as_ticket_after();

create or replace function app.as_ticket_deleted()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  perform app.audit('deleted', 'ticket', old.id, null, 'TKT-' || old.number || ' · ' || old.subject);
  return null;
end;
$$;
create trigger as_tickets_deleted after delete on public.as_tickets
  for each row execute function app.as_ticket_deleted();

-- A message: keeps the ticket's "last heard" times, and moves the status along.
create or replace function app.as_message_added()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  t public.as_tickets%rowtype;
begin
  if new.kind = 'event' then return null; end if;
  select * into t from public.as_tickets where id = new.ticket_id;
  if new.kind = 'reply' then
    update public.as_tickets
       set first_response_at = coalesce(first_response_at, new.created_at), last_staff_at = new.created_at,
           status = case when status in ('new', 'assigned') then 'in_progress' else status end
     where id = new.ticket_id;
  elsif new.kind = 'customer' then
    update public.as_tickets
       set last_customer_at = new.created_at,
           status = case when status in ('waiting', 'resolved', 'closed') then 'in_progress' else status end
     where id = new.ticket_id;
    -- Tell whoever has it (or the managers, if nobody does).
    if t.assigned_to is not null then
      if t.assigned_to is distinct from auth.uid() then
        perform app.notify(t.assigned_to, 'ticket.customer', 'TKT-' || t.number || ': the customer wrote', left(new.body, 200), '/aftersales/tickets/' || t.number);
      end if;
    end if;
  else
    update public.as_tickets set updated_at = now() where id = new.ticket_id;
  end if;
  return null;
end;
$$;
create trigger as_messages_added after insert on public.as_messages
  for each row execute function app.as_message_added();

